 10	namespace SolutionOne_BusinessLogicLayer.Services.Payroll.Implementation;
 11	
 12	/// <summary>
 13	/// F&amp;F Configuration business rules. Admin/HR Admin only — enforced on every read and write,
 14	/// not just hidden from the menu.
 15	/// </summary>
 16	public class FnfConfigService(
 17	    IFnfConfigRepository repository,
 18	    ILeaveRepository leaveRepository,
 19	    ISalaryHeadMasterRepository salaryHeadRepository,
 20	    IRequestMetadata requestMetadata,
 21	    ILogger<FnfConfigService> logger
 22	) : IFnfConfigService
 23	{
 24	    private readonly IFnfConfigRepository _repository = repository;
 25	    private readonly ILeaveRepository _leaveRepository = leaveRepository;
 26	    private readonly ISalaryHeadMasterRepository _salaryHeadRepository = salaryHeadRepository;
 27	    private readonly IRequestMetadata _requestMetadata = requestMetadata;
 28	    private readonly ILogger<FnfConfigService> _logger = logger;
 29	
 30	    /// <summary>
 31	    /// Checks the figures and the base/divisor names, returning the first problem or null.
 32	    /// </summary>
 33	    /// <remarks>
 34	    /// Validated here rather than with [Range] attributes: [ApiController]'s automatic model
 35	    /// validation is not suppressed in this app, so an attribute failure returns ASP.NET
 36	    /// ProblemDetails instead of the ResponseModel.Message the Angular toasts read - the user
 37	    /// would see a generic failure with no reason.
 38	    ///
 39	    /// What makes this worth checking at all is that nothing downstream complains. A zero
 40	    /// divisor does not throw: FnfCalculationService quietly substitutes 26, and an unrecognised
 41	    /// base silently computes on Basic. The settlement is then produced from figures the
 42	    /// configuration screen does not show, and the approver's policy line - built from the
 43	    /// STORED values - tells them "/0" or "on Grosss" while the engine used something else.
 44	    /// Wrong money, described confidently. Refusing the save keeps the two in step.
 45	    /// </remarks>
 46	    private static string? ValidateNumbersAndBases(UpdateFnfConfigModel model)
 47	    {
 48	        // Used as the fallback divisor in every branch of the per-day-rate calculation, including
 49	        // the MonthDays/WorkingDays ones, so it has to be sane whatever the type is.
 50	        if (model.PerDayRateDivisorValue <= 0)
 51	            return "Per-day-rate divisor must be greater than zero - it is what the daily rate is divided by.";
 52	
 53	        if (model.GratuityDivisor <= 0)
 54	            return "Gratuity divisor must be greater than zero - it is what the gratuity formula divides by.";
 55	
 56	        if (model.GratuityEligibleYears < 0)
 57	            return "Gratuity eligibility cannot be a negative number of years.";
 58	
 59	        if (model.GratuityDaysPerYear < 0)
 60	            return "Gratuity days per year cannot be negative.";
 61	
 62	        if (model.ComplianceWindowDays < 0)
 63	            return "The compliance window cannot be a negative number of days.";
 64	
 65	        if (model.EncashmentCapDays.HasValue && model.EncashmentCapDays.Value < 0)
 66	            return "The leave-encashment cap cannot be negative. Leave it empty for no cap.";
 67	
 68	        // These must match what the calculation understands; anything else falls through to a
 69	        // default there without complaint.
 70	        if (!IsOneOf(model.GratuityBase, "Basic", "Basic+DA", "Gross"))
 71	            return "Gratuity base must be Basic, Basic+DA or Gross.";
 72	
 73	        if (!IsOneOf(model.PerDayRateBase, "Basic", "Gross", "CTC"))
 74	            return "Per-day-rate base must be Basic, Gross or CTC.";
 75	
 76	        if (!IsOneOf(model.PerDayRateDivisorType, "Fixed", "MonthDays", "WorkingDays"))
 77	            return "Per-day-rate divisor type must be Fixed, MonthDays or WorkingDays.";
 78	
 79	        return null;
 80	    }
 81	
 82	    private static bool IsOneOf(string? value, params string[] allowed) =>
 83	        allowed.Any(a => string.Equals(value?.Trim(), a, StringComparison.OrdinalIgnoreCase));
 84	
 85	    private static bool IsAdminRole(string role) =>
 86	        string.Equals(role, "Admin", StringComparison.OrdinalIgnoreCase)
 87	        || string.Equals(role, "HR Admin", StringComparison.OrdinalIgnoreCase);
 88	
 89	    public async Task<ResponseModel> GetConfigAsync()
 90	    {
 91	        var res = new ResponseModel();
 92	        var companyId = _requestMetadata.CompanyId;
 93	        var role = _requestMetadata.UserRole;
 94	        try
 95	        {
 96	            if (!IsAdminRole(role))
 97	                return Fail(res, HttpStatusCode.Forbidden, "F&F Configuration is limited to Admin and HR Admin.");
 98	
 99	            var model = await _repository.GetConfigAsync(companyId);
100	            if (model == null)
101	                return Fail(res, HttpStatusCode.NotFound,
102	                    "No F&F configuration exists for this company. This should have been seeded automatically - check with an administrator.");
103	
104	            model.EncashableLeaveCount = await _leaveRepository.CountEncashable(companyId);
105	            return Success(res, "Fetched F&F configuration.", model);
106	        }
107	        catch (Exception e)
108	        {
109	            _logger.LogError(e, "Exception while fetching F&F configuration");
110	            return Fail(res, HttpStatusCode.InternalServerError, e.Message);
111	        }
112	    }
113	
114	    public async Task<ResponseModel> UpdateConfigAsync(UpdateFnfConfigModel model)
115	    {
116	        var res = new ResponseModel();
117	        var companyId = _requestMetadata.CompanyId;
118	        var role = _requestMetadata.UserRole;
119	        var userId = _requestMetadata.UserId;
120	        try
121	        {
122	            if (!IsAdminRole(role))
123	                return Fail(res, HttpStatusCode.Forbidden, "F&F Configuration is limited to Admin and HR Admin.");
124	
125	            var existing = await _repository.GetConfigAsync(companyId);
126	            if (existing == null)
127	                return Fail(res, HttpStatusCode.NotFound, "No F&F configuration exists for this company.");
128	
129	            var invalid = ValidateNumbersAndBases(model);
130	            if (invalid != null) return Fail(res, HttpStatusCode.BadRequest, invalid);
131	
132	            var heads = await _salaryHeadRepository.GetAllSalaryHeadMasters(companyId);
133	            var activeHeadIds = heads.Where(h => h.Status).Select(h => h.SalaryHeadMasterId).ToHashSet();
134	
135	            foreach (var (headId, label) in new (long?, string)[]
136	            {
137	                (model.GratuityHeadId, "Gratuity"), (model.LeaveEncashHeadId, "Leave encashment"),
138	                (model.NoticePayHeadId, "Notice pay"), (model.NoticeRecoveryHeadId, "Notice recovery"),
139	                (model.AssetRecoveryHeadId, "Asset recovery"), (model.LoanRecoveryHeadId, "Loan recovery"),
140	            })
141	            {
142	                if (headId.HasValue && !activeHeadIds.Contains(headId.Value))
143	                    return Fail(res, HttpStatusCode.BadRequest, $"The salary head selected for {label} is not valid for your company.");
144	            }
145	
146	            await _repository.UpdateConfigAsync(model, userId, companyId);
147	            return Success(res, "F&F configuration saved.");
148	        }
149	        catch (Exception e)
150	        {
151	            _logger.LogError(e, "Exception while updating F&F configuration");
152	            return Fail(res, HttpStatusCode.InternalServerError, e.Message);
153	        }
154	    }
155	
156	    public async Task<ResponseModel> GetEncashableLeaveTypesAsync()
157	    {
158	        var res = new ResponseModel();
159	        var companyId = _requestMetadata.CompanyId;
160	        var role = _requestMetadata.UserRole;
161	        try
162	        {
163	            if (!IsAdminRole(role))
164	                return Fail(res, HttpStatusCode.Forbidden, "F&F Configuration is limited to Admin and HR Admin.");
165	
166	            var leaves = await _leaveRepository.GetEncashableCandidates(companyId);
167	            var model = leaves.Select(l => new ListEncashableLeaveModel
168	            {
169	                LeaveMasterId = l.LeaveMasterId,
170	                Code = l.Code?.Trim() ?? string.Empty,
171	                Name = l.Name,
172	                IsPaidLeave = l.IsPaidLeave,
173	                CarryForward = l.CarryForward,
174	                IsEncashable = l.IsEncashable,
175	            }).ToList();
176	
177	            return Success(res, "Fetched encashable leave types.", model);
178	        }
179	        catch (Exception e)
180	        {
181	            _logger.LogError(e, "Exception while fetching encashable leave types");
182	            return Fail(res, HttpStatusCode.InternalServerError, e.Message);
183	        }
184	    }
185	
186	    public async Task<ResponseModel> UpdateEncashableFlagAsync(int leaveMasterId, bool isEncashable)
187	    {
188	        var res = new ResponseModel();
189	        var companyId = _requestMetadata.CompanyId;
190	        var role = _requestMetadata.UserRole;
191	        try
192	        {
193	            if (!IsAdminRole(role))
194	                return Fail(res, HttpStatusCode.Forbidden, "F&F Configuration is limited to Admin and HR Admin.");
195	
196	            var candidates = await _leaveRepository.GetEncashableCandidates(companyId);
197	            if (!candidates.Any(x => x.LeaveMasterId == leaveMasterId))
198	                return Fail(res, HttpStatusCode.NotFound, "That leave type was not found.");
199	
200	            await _leaveRepository.UpdateEncashableFlag(leaveMasterId, isEncashable);
201	            return Success(res, "Updated.");
202	        }
203	        catch (Exception e)
204	        {
205	            _logger.LogError(e, "Exception while updating encashable flag for leave {Id}", leaveMasterId);
206	            return Fail(res, HttpStatusCode.InternalServerError, e.Message);
207	        }
208	    }
