210	    public async Task<ResponseModel> GetClearanceDepartmentsAsync()
211	    {
212	        var res = new ResponseModel();
213	        var companyId = _requestMetadata.CompanyId;
214	        var role = _requestMetadata.UserRole;
215	        try
216	        {
217	            if (!IsAdminRole(role))
218	                return Fail(res, HttpStatusCode.Forbidden, "F&F Configuration is limited to Admin and HR Admin.");
219	
220	            var (useCustom, options) = await _repository.GetClearanceDepartmentPickerAsync(companyId);
221	            var model = new FnfClearanceDepartmentConfigModel
222	            {
223	                UseCustomClearanceDepartments = useCustom,
224	                Departments = options,
225	            };
226	            return Success(res, "Fetched exit-clearance department options.", model);
227	        }
228	        catch (Exception e)
229	        {
230	            _logger.LogError(e, "Exception while fetching F&F clearance department options");
231	            return Fail(res, HttpStatusCode.InternalServerError, e.Message);
232	        }
233	    }
234	
235	    public async Task<ResponseModel> UpdateClearanceDepartmentsAsync(UpdateFnfClearanceDepartmentsModel model)
236	    {
237	        var res = new ResponseModel();
238	        var companyId = _requestMetadata.CompanyId;
239	        var role = _requestMetadata.UserRole;
240	        var userId = _requestMetadata.UserId;
241	        try
242	        {
243	            if (!IsAdminRole(role))
244	                return Fail(res, HttpStatusCode.Forbidden, "F&F Configuration is limited to Admin and HR Admin.");
245	
246	            var selected = model.SelectedDepartments ?? new List<SelectedFnfClearanceDepartmentModel>();
247	
248	            var duplicate = selected.GroupBy(x => x.DepartmentMasterId).FirstOrDefault(g => g.Count() > 1);
249	            if (duplicate != null)
250	                return Fail(res, HttpStatusCode.BadRequest, $"Department {duplicate.Key} appears more than once in the selection.");
251	
252	            if (selected.Count > 0)
253	            {
254	                var (_, options) = await _repository.GetClearanceDepartmentPickerAsync(companyId);
255	                var validIds = options.Select(o => o.DepartmentMasterId).ToHashSet();
256	                var invalid = selected.Where(s => !validIds.Contains(s.DepartmentMasterId)).Select(s => s.DepartmentMasterId).ToList();
257	                if (invalid.Count > 0)
258	                    return Fail(res, HttpStatusCode.BadRequest,
259	                        $"These departments do not belong to your company: {string.Join(", ", invalid)}.");
260	            }
261	
262	            await _repository.ReplaceClearanceDepartmentsAsync(companyId, selected, userId);
263	            return Success(res, selected.Count == 0
264	                ? "Saved - no departments selected, so only Reporting Manager clearance will be required for future exits."
265	                : $"Saved {selected.Count} clearance department(s).");
266	        }
267	        catch (Exception e)
268	        {
269	            _logger.LogError(e, "Exception while updating F&F clearance department selection");
270	            return Fail(res, HttpStatusCode.InternalServerError, e.Message);
271	        }
272	    }
273	
274	    private static ResponseModel Success(ResponseModel res, string message, object? data = null)
275	    {
276	        res.IsSuccess = true; res.Status = HttpStatusCode.OK; res.Message = message; res.Data = data;
277	        return res;
278	    }
279	
280	    private static ResponseModel Fail(ResponseModel res, HttpStatusCode status, string message)
281	    {
282	        res.IsSuccess = false; res.Status = status; res.Message = message;
283	        return res;
284	    }
285	}
286	using SolutionOne_Core.PayrollModels;
287	using SolutionOne_DataAccessLayer.Repositories.Common.Interface;
288	using SolutionOne_DataAccessLayer.Repositories.Payroll.Interface;
289	
290	namespace SolutionOne_DataAccessLayer.Repositories.Payroll.Implementation;
291	
292	public class FnfConfigRepository(IDapperContext tx, IDapperRepository repo) : IFnfConfigRepository
293	{
294	    private readonly IDapperContext _tx = tx;
295	    private readonly IDapperRepository _repo = repo;
296	
297	    private const string _SelectSql = @"
298	        SELECT FNFConfigID AS FnfConfigId, CompanyMasterID AS CompanyMasterId,
299	               GratuityEnabled, GratuityEligibleYears, GratuityDaysPerYear, GratuityDivisor,
300	               GratuityBase, PerDayRateBase, PerDayRateDivisorType, PerDayRateDivisorValue,
301	               EncashmentCapDays, RecoverAssetsOnExit, SuppressLoanEMIOnSettlement,
302	               ComplianceWindowDays, RequireExitFormality,
303	               GratuityHeadID AS GratuityHeadId, LeaveEncashHeadID AS LeaveEncashHeadId,
304	               NoticePayHeadID AS NoticePayHeadId, NoticeRecoveryHeadID AS NoticeRecoveryHeadId,
305	               AssetRecoveryHeadID AS AssetRecoveryHeadId, LoanRecoveryHeadID AS LoanRecoveryHeadId
306	        FROM   HR_FNFConfig
307	        WHERE  CompanyMasterID = @CompanyMasterId AND Status = 1";
308	
309	    public async Task<FnfConfigModel?> GetConfigAsync(long companyMasterId) =>
310	        await _repo.QueryFirstOrDefaultAsync<FnfConfigModel>(_SelectSql, new { CompanyMasterId = companyMasterId });
311	
312	    public async Task UpdateConfigAsync(UpdateFnfConfigModel model, long userId, long companyMasterId)
313	    {
314	        await _tx.BeginTransactionAsync();
315	        try
316	        {
317	            const string sql = @"
318	                UPDATE HR_FNFConfig
319	                SET    GratuityEnabled = @GratuityEnabled,
320	                       GratuityEligibleYears = @GratuityEligibleYears,
321	                       GratuityDaysPerYear = @GratuityDaysPerYear,
322	                       GratuityDivisor = @GratuityDivisor,
323	                       GratuityBase = @GratuityBase,
324	                       PerDayRateBase = @PerDayRateBase,
325	                       PerDayRateDivisorType = @PerDayRateDivisorType,
326	                       PerDayRateDivisorValue = @PerDayRateDivisorValue,
327	                       EncashmentCapDays = @EncashmentCapDays,
328	                       RecoverAssetsOnExit = @RecoverAssetsOnExit,
329	                       SuppressLoanEMIOnSettlement = @SuppressLoanEMIOnSettlement,
330	                       ComplianceWindowDays = @ComplianceWindowDays,
331	                       RequireExitFormality = @RequireExitFormality,
332	                       GratuityHeadID = @GratuityHeadId,
333	                       LeaveEncashHeadID = @LeaveEncashHeadId,
334	                       NoticePayHeadID = @NoticePayHeadId,
335	                       NoticeRecoveryHeadID = @NoticeRecoveryHeadId,
336	                       AssetRecoveryHeadID = @AssetRecoveryHeadId,
337	                       LoanRecoveryHeadID = @LoanRecoveryHeadId,
338	                       EditUserMasterID = @UserId,
339	                       EditUserDateTime = @Now
340	                WHERE  CompanyMasterID = @CompanyMasterId AND Status = 1";
341	                       // CompanyMasterId, Status and the Entry* audit pair are deliberately absent
342	                       // from this SET list.
343	
344	            await _repo.ExecuteAsync(sql, new
345	            {
346	                model.GratuityEnabled, model.GratuityEligibleYears, model.GratuityDaysPerYear,
347	                model.GratuityDivisor, model.GratuityBase, model.PerDayRateBase,
348	                model.PerDayRateDivisorType, model.PerDayRateDivisorValue, model.EncashmentCapDays,
349	                model.RecoverAssetsOnExit, model.SuppressLoanEMIOnSettlement,
350	                model.ComplianceWindowDays, model.RequireExitFormality,
351	                model.GratuityHeadId, model.LeaveEncashHeadId, model.NoticePayHeadId,
352	                model.NoticeRecoveryHeadId, model.AssetRecoveryHeadId, model.LoanRecoveryHeadId,
353	                UserId = userId, Now = DateTime.Now, CompanyMasterId = companyMasterId,
354	            });
355	
356	            await _tx.CommitAsync();
357	        }
358	        catch
359	        {
360	            await _tx.RollbackAsync();
361	            throw;
362	        }
363	    }
364	
365	    public async Task<(bool UseCustom, List<FnfClearanceDepartmentOptionModel> Options)> GetClearanceDepartmentPickerAsync(long companyMasterId)
366	    {
367	        var useCustom = await _repo.ExecuteScalarAsync<bool>(
368	            "SELECT ISNULL(UseCustomClearanceDepartments, 0) FROM HR_FNFConfig WHERE CompanyMasterID = @CompanyMasterId AND Status = 1",
369	            new { CompanyMasterId = companyMasterId });
370	
371	        const string sql = @"
372	            SELECT D.DepartmentMasterID AS DepartmentMasterId, D.DepartmentCode, D.DepartmentName,
373	                   CASE WHEN C.FNFClearanceDepartmentID IS NULL THEN 0 ELSE 1 END AS IsSelected,
374	                   C.ChecklistHint, ISNULL(C.SortOrder, 0) AS SortOrder
375	            FROM   HR_DepartmentMaster D
376	            LEFT   JOIN HR_FNFClearanceDepartment C
377	                   ON  C.DepartmentMasterID = D.DepartmentMasterID AND C.CompanyMasterID = @CompanyMasterId
378	            WHERE  D.CompanyMasterID = @CompanyMasterId AND D.Status = 1
379	            ORDER  BY ISNULL(C.SortOrder, 999), D.DepartmentName";
380	
381	        var options = (await _repo.QueryAsync<FnfClearanceDepartmentOptionModel>(sql, new { CompanyMasterId = companyMasterId })).ToList();
382	        return (useCustom, options);
383	    }
384	
385	    public async Task ReplaceClearanceDepartmentsAsync(long companyMasterId, List<SelectedFnfClearanceDepartmentModel> selected, long userId)
386	    {
387	        await _tx.BeginTransactionAsync();
388	        try
389	        {
390	            await _repo.ExecuteAsync(
391	                "DELETE FROM HR_FNFClearanceDepartment WHERE CompanyMasterID = @CompanyMasterId",
392	                new { CompanyMasterId = companyMasterId });
393	
394	            if (selected.Count > 0)
395	            {
396	                const string insertSql = @"
397	                    INSERT INTO HR_FNFClearanceDepartment
398	                        (CompanyMasterID, DepartmentMasterID, ChecklistHint, SortOrder, IsActive,
399	                         EntryUserMasterID, EntryUserDateTime)
400	                    VALUES
401	                        (@CompanyMasterId, @DepartmentMasterId, @ChecklistHint, @SortOrder, 1,
402	                         @UserId, @Now)";
403	
404	                var rows = selected.Select(s => new
405	                {
406	                    CompanyMasterId = companyMasterId, s.DepartmentMasterId, s.ChecklistHint, s.SortOrder,
407	                    UserId = userId, Now = DateTime.Now,
408	                });
409	                await _repo.ExecuteAsync(insertSql, rows);
410	            }
411	
412	            // Saving - even an empty selection - is what flips a company off the fixed legacy
413	            // checklist. A zero-row selection means "no department checkpoints", not "unconfigured".
414	            await _repo.ExecuteAsync(
415	                "UPDATE HR_FNFConfig SET UseCustomClearanceDepartments = 1 WHERE CompanyMasterID = @CompanyMasterId",
416	                new { CompanyMasterId = companyMasterId });
417	
418	            await _tx.CommitAsync();
419	        }
420	        catch
421	        {
422	            await _tx.RollbackAsync();
423	            throw;
424	        }
425	    }
426	}

