274	    private static ResponseModel Success(ResponseModel res, string message, object? data = null)
275	    {
276	        res.IsSuccess = true; res.Status = HttpStatusCode.OK; res.Message = message; res.Data = data;
277	        return res;
278	    }
279	
280	    private static ResponseModel Fail(ResponseModel res, HttpStatusCode status, string message)
281	    {
282	        res.IsSuccess = false; res.Status = status; res.Message = message;
283	        return res;
284	    }
