     7	/// <summary>
     8	/// F&amp;F Configuration — the per-company rules the settlement calculation reads.
     9	///
    10	/// Everything a client could reasonably do differently lives here rather than in code: the
    11	/// per-day rate basis, the gratuity formula, the encashment cap, which salary head pays each
    12	/// component, and whether Exit Formality gates F&amp;F at all. This installation is the Africa
    13	/// statutory pack while others are India, so none of it can be hard-coded.
    14	///
    15	/// One row per company (<c>HR_FNFConfig</c>), seeded by migration 110. This screen edits the
    16	/// row for the company the user is signed into — it never shows another company's rules.
    17	/// </summary>
    18	public partial class Payroll_FNFConfiguration : System.Web.UI.Page
    19	{
    20	    private long CompanyId
    21	    {
    22	        get { return Session["CompanyID"] != null ? Convert.ToInt64(Session["CompanyID"]) : 0; }
    23	    }
    24	
    25	    private int UserId
    26	    {
    27	        get { return Session["UserID"] != null ? Convert.ToInt32(Session["UserID"]) : 0; }
    28	    }
    29	
    30	    private static SqlConnection CreateConnection()
    31	    {
    32	        return new SqlConnection(DbConnectionFactory.GetConnectionString());
    33	    }
    34	
    35	    /// <summary>
    36	    /// Admin / HR Admin only. These settings decide what every settlement in the company pays
    37	    /// — the gratuity formula, the per-day rate and which salary head each component is paid
    38	    /// through — so an ordinary user must not be able to change them even if somebody grants
    39	    /// them the menu right by accident. Checked here AND in the save path, because hiding a
    40	    /// screen is not access control: the callback is reachable from a second tab.
    41	    /// </summary>
    42	    private bool IsAllowed
    43	    {
    44	        get { return RoleHelper.IsAdmin(Session["UserRole"]); }
    45	    }
    46	
    47	    private void DenyAccess()
    48	    {
    49	        litBanner.Text =
    50	            "<div class=\"cfg-banner\">These settings decide what every settlement in the company "
    51	          + "pays, so they are limited to Admin and HR Admin. Ask an administrator if a rule needs "
    52	          + "changing.</div>";
    53	        CfgTabs.Visible = false;
    54	    }
    55	
    56	    protected void Page_Load(object sender, EventArgs e)
    57	    {
    58	        if (!IsAllowed) { DenyAccess(); return; }
    59	
    60	        if (!IsPostBack)
    61	        {
    62	            LoadHeadCombos();
    63	            LoadConfig();
    64	            LeaveGrid.DataBind();
    65	        }
    66	    }
    67	
    68	    protected void CfgPanel_Callback(object sender, CallbackEventArgsBase e)
    69	    {
    70	        string[] parts = (e.Parameter ?? string.Empty).Split('|');
    71	        if (parts.Length < 2) return;
    72	
    73	        // Re-checked on every callback, not just on the first render.
    74	        if (!IsAllowed)
    75	        {
    76	            CfgPanel.JSProperties["cpMsg"] = "Only Admin or HR Admin can change these settings.";
    77	            DenyAccess();
    78	            return;
    79	        }
    80	
    81	        try
    82	        {
    83	            switch (parts[0])
    84	            {
    85	                case "Load":
    86	                    LoadHeadCombos();
    87	                    LoadConfig();
    88	                    LeaveGrid.DataBind();
    89	                    break;
    90	                case "Save":
    91	                    SaveConfig();
    92	                    break;
    93	                case "GratuityToggled":
    94	                    // Only a hint; the fields stay enabled so the rule can be filled in before
    95	                    // switching it on.
    96	                    RenderBanner(parts[1] == "1");
    97	                    break;
    98	            }
    99	        }
   100	        catch (Exception ex)
   101	        {
   102	            ErrorLogHelper.Log(ex, "FNFConfiguration." + parts[0]);
   103	            CfgPanel.JSProperties["cpMsg"] = ErrorLogHelper.FriendlyMessage;
   104	        }
   105	    }
   106	
   107	    /// <summary>
   108	    /// Every active salary head of THIS company. A head is company-scoped
   109	    /// (<c>HR_SalaryHeadMaster.CompanyMasterID</c>), so offering another company's heads would
   110	    /// let a settlement pay against a head payroll will never see.
   111	    /// </summary>
   112	    private void LoadHeadCombos()
   113	    {
   114	        const string sql = @"
   115	            SELECT SalaryHeadMasterID,
   116	                   ISNULL(Name, '') + ISNULL(' (' + NULLIF(LTRIM(RTRIM(Code)),'') + ')', '') AS Name
   117	            FROM   dbo.HR_SalaryHeadMaster
   118	            WHERE  Status = 1 AND CompanyMasterID = @CompanyID
   119	            ORDER  BY Name";
   120	
   121	        try
   122	        {
   123	            using (SqlConnection conn = CreateConnection())
   124	            using (var cmd = new SqlCommand(sql, conn))
   125	            {
   126	                cmd.Parameters.AddWithValue("@CompanyID", CompanyId);
   127	                var dt = new DataTable();
   128	                using (var da = new SqlDataAdapter(cmd)) da.Fill(dt);
   129	
   130	                foreach (ASPxComboBox combo in new[] { cmbHeadGratuity, cmbHeadEncash, cmbHeadNoticePay,
   131	                                                        cmbHeadNoticeRec, cmbHeadAsset, cmbHeadLoan })
   132	                {
   133	                    combo.DataSource = dt;
   134	                    combo.ValueType = typeof(long);
   135	                    combo.DataBind();
   136	                }
   137	            }
   138	        }
   139	        catch (Exception ex)
   140	        {
   141	            ErrorLogHelper.Log(ex, "FNFConfiguration.LoadHeads");
   142	        }
   143	    }
   144	
   145	    private void LoadConfig()
   146	    {
   147	        const string sql = "SELECT * FROM dbo.HR_FNFConfig WHERE CompanyMasterID = @CompanyID AND Status = 1";
   148	
   149	        DataRow row = null;
   150	        using (SqlConnection conn = CreateConnection())
   151	        using (var cmd = new SqlCommand(sql, conn))
   152	        {
   153	            cmd.Parameters.AddWithValue("@CompanyID", CompanyId);
   154	            var dt = new DataTable();
   155	            using (var da = new SqlDataAdapter(cmd)) da.Fill(dt);
   156	            if (dt.Rows.Count > 0) row = dt.Rows[0];
   157	        }
   158	
   159	        if (row == null)
   160	        {
   161	            litBanner.Text =
   162	                "<div class=\"cfg-banner\">No F&amp;F configuration row exists for this company. "
   163	              + "Migration 110 seeds one per company - if this persists, check HR_FNFConfig.</div>";
   164	            return;
   165	        }
   166	
   167	        cmbRateBase.Value      = Convert.ToString(row["PerDayRateBase"]);
   168	        cmbDivisorType.Value   = Convert.ToString(row["PerDayRateDivisorType"]);
   169	        spnDivisor.Value       = row["PerDayRateDivisorValue"];
   170	
   171	        chkGratuity.Checked    = ToBool(row["GratuityEnabled"]);
   172	        spnEligibleYears.Value = row["GratuityEligibleYears"];
   173	        spnDaysPerYear.Value   = row["GratuityDaysPerYear"];
   174	        spnGratuityDivisor.Value = row["GratuityDivisor"];
   175	        cmbGratuityBase.Value  = Convert.ToString(row["GratuityBase"]);
   176	
   177	        spnCapDays.Value       = (row["EncashmentCapDays"] == DBNull.Value) ? null : row["EncashmentCapDays"];
   178	        chkRecoverAssets.Checked = ToBool(row["RecoverAssetsOnExit"]);
   179	        chkSuppressLoan.Checked  = ToBool(row["SuppressLoanEMIOnSettlement"]);
   180	        spnWindowDays.Value    = ColumnOr(row, "ComplianceWindowDays", 90);
   181	        chkRequireExit.Checked = ToBool(ColumnOr(row, "RequireExitFormality", true));
   182	
   183	        cmbHeadGratuity.Value  = NullIfDbNull(ColumnOr(row, "GratuityHeadID", null));
   184	        cmbHeadEncash.Value    = NullIfDbNull(ColumnOr(row, "LeaveEncashHeadID", null));
   185	        cmbHeadNoticePay.Value = NullIfDbNull(ColumnOr(row, "NoticePayHeadID", null));
   186	        cmbHeadNoticeRec.Value = NullIfDbNull(ColumnOr(row, "NoticeRecoveryHeadID", null));
   187	        cmbHeadAsset.Value     = NullIfDbNull(ColumnOr(row, "AssetRecoveryHeadID", null));
   188	        cmbHeadLoan.Value      = NullIfDbNull(ColumnOr(row, "LoanRecoveryHeadID", null));
   189	
   190	        RenderBanner(chkGratuity.Checked);
   191	    }
   192	
   193	    /// <summary>
   194	    /// Says out loud what the current settings mean, because the consequences are easy to miss:
   195	    /// gratuity off means every settlement quietly pays zero for it, and no encashable leave
   196	    /// type means the same for encashment.
   197	    /// </summary>
   198	    private void RenderBanner(bool gratuityOn)
   199	    {
   200	        int encashable = 0;
   201	        try
   202	        {
   203	            using (SqlConnection conn = CreateConnection())
   204	            using (var cmd = new SqlCommand(@"
   205	                SELECT COUNT(*) FROM dbo.HR_LeaveMaster
   206	                WHERE ISNULL(IsEncashable, 0) = 1
   207	                  AND (CompanyMasterID = @CompanyID OR CompanyMasterID IS NULL)", conn))
   208	            {
   209	                cmd.Parameters.AddWithValue("@CompanyID", CompanyId);
   210	                conn.Open();
   211	                encashable = Convert.ToInt32(cmd.ExecuteScalar());
   212	            }
   213	        }
   214	        catch (Exception ex) { ErrorLogHelper.Log(ex, "FNFConfiguration.Banner"); }
   215	
   216	        var sb = new System.Text.StringBuilder();
   217	        sb.Append("<div class=\"cfg-banner\">");
   218	        sb.Append(gratuityOn
   219	            ? "Gratuity is <b>on</b>. "
   220	            : "Gratuity is <b>off</b>, so every settlement will show it as zero with a note. ");
   221	        sb.Append(encashable > 0
   222	            ? encashable + " leave type(s) are encashable."
   223	            : "No leave type is encashable, so leave encashment will always be zero - tick them on the Encashable Leave tab.");
   224	        sb.Append("</div>");
   225	        litBanner.Text = sb.ToString();
   226	    }
   227	
   228	    private void SaveConfig()
