     6	
     7	/// <summary>
     8	/// Exit Formality — the stage between a manager approving a resignation and F&amp;F opening.
     9	///
    10	/// It exists to answer one question before any settlement is calculated: <b>is anything
    11	/// still outstanding?</b> An unreturned laptop or an unpaid advance has to be known about,
    12	/// because each becomes a deduction. Calculating first and discovering dues later is how a
    13	/// settlement gets paid twice.
    14	///
    15	/// Three parts, as the flow describes them:
    16	///   Exit Interview      — captured on the exit header (one interview per exit).
    17	///   Asset Return        — NOT stored here. The Assets module already records issues and
    18	///                         returns in more detail than a new table would, including
    19	///                         Condition, MissingItems, Damage and Fine on
    20	///                         HR_AssetReturnDetail. This service READS the outstanding
    21	///                         balance from there. Duplicating it would split an asset's
    22	///                         history across two modules and let the two disagree.
    23	///   Dept. Clearance     — five rows per exit in HR_ExitClearance, each able to raise dues
    24	///                         that flow into the F&amp;F case as a recovery.
    25	///
    26	/// No System.Web dependency, so it compiles standalone with csc.exe and can be driven
    27	/// against the live database inside a rolled-back transaction.
    28	/// </summary>
    29	public static class ExitFormalityService
    30	{
    31	    /// <summary>Every lifecycle date on HR_EmployeeMaster uses this as its "not set"
    32	    /// sentinel instead of NULL.</summary>
    33	    public static readonly DateTime EpochDate = new DateTime(1900, 1, 1);
    34	
    35	    public const string InterviewPending      = "Pending";
    36	    public const string InterviewScheduled    = "Scheduled";
    37	    public const string InterviewCompleted    = "Completed";
    38	    public const string InterviewUnavailable  = "Employee Not Available";
    39	    public const string InterviewSkipped      = "Skipped";
    40	
    41	    public const string ClearancePending   = "Pending";
    42	    public const string ClearanceCleared   = "Cleared";
    43	    public const string ClearanceObjection = "Objection Raised";
    44	
    45	    // -------------------------------------------------------------------------
    46	    //  The five departments
    47	    // -------------------------------------------------------------------------
    48	
    49	    public sealed class ClearanceDepartment
    50	    {
    51	        public string Code;
    52	        public string Name;
    53	        public string Hint;
    54	        public int SortOrder;
    55	    }
    56	
    57	    /// <summary>
    58	    /// The checklist hints are seeded onto each row so the person clearing it can see what
    59	    /// they are being asked to confirm, rather than having to remember.
    60	    /// </summary>
    61	    public static IList<ClearanceDepartment> Departments()
    62	    {
    63	        return new List<ClearanceDepartment>
    64	        {
    65	            new ClearanceDepartment { Code = "IT", Name = "IT Department", SortOrder = 1,
    66	                Hint = "System access revoked, email / login deactivated, software licences released." },
    67	            new ClearanceDepartment { Code = "FINANCE", Name = "Finance Department", SortOrder = 2,
    68	                Hint = "No loan, advance or unsettled expense reimbursement outstanding." },
    69	            new ClearanceDepartment { Code = "ADMIN", Name = "Admin Department", SortOrder = 3,
    70	                Hint = "Locker, parking pass, office keys and ID / access card returned." },
    71	            new ClearanceDepartment { Code = "HR", Name = "HR Department", SortOrder = 4,
    72	                Hint = "Documents submitted, final address and bank details confirmed." },
    73	            new ClearanceDepartment { Code = "MANAGER", Name = "Reporting Manager", SortOrder = 5,
    74	                Hint = "Work handover and knowledge transfer complete." },
    75	        };
    76	    }
