    78	    // -------------------------------------------------------------------------
    79	    //  Opening an exit
    80	    // -------------------------------------------------------------------------
    81	
    82	    public static string NextExitNo(SqlConnection conn, SqlTransaction tx, int year)
    83	    {
    84	        string prefix = "EXIT-" + year.ToString(CultureInfo.InvariantCulture) + "-";
    85	
    86	        using (var cmd = new SqlCommand(@"
    87	            SELECT MAX(CAST(RIGHT(ExitNo, 5) AS int))
    88	            FROM   dbo.HR_ExitFormality WITH (UPDLOCK, HOLDLOCK)
    89	            WHERE  ExitNo LIKE @Prefix + '[0-9][0-9][0-9][0-9][0-9]'", conn, tx))
    90	        {
    91	            cmd.Parameters.AddWithValue("@Prefix", prefix);
    92	            object max = cmd.ExecuteScalar();
    93	            int next = (max == null || max == DBNull.Value) ? 1 : Convert.ToInt32(max) + 1;
    94	            return prefix + next.ToString("00000", CultureInfo.InvariantCulture);
    95	        }
    96	    }
    97	
    98	    /// <summary>
    99	    /// Employees who have resigned or left and do not already have a live exit record.
   100	    /// Same epoch-aware test F&amp;F uses — both dates carry 1900-01-01 when unset.
   101	    /// </summary>
   102	    public static DataTable EmployeesNeedingExit(SqlConnection conn, SqlTransaction tx, long companyId)
   103	    {
   104	        const string sql = @"
   105	            SELECT EM.EmployeeMasterID,
   106	                   LTRIM(ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.FirstName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.FatherName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.LastName)),''), ''))
   107	                       + ' (' + ISNULL(EM.Code, '') + ')' AS Name
   108	            FROM   dbo.HR_EmployeeMaster EM
   109	            WHERE  EM.Status = 1
   110	              AND  EM.CompanyMasterID = @CompanyID
   111	              AND  ( (EM.ResignDate IS NOT NULL AND EM.ResignDate > @Epoch)
   112	                  OR (EM.DateOfLeft IS NOT NULL AND EM.DateOfLeft > @Epoch) )
   113	              AND  NOT EXISTS (SELECT 1 FROM dbo.HR_ExitFormality X
   114	                               WHERE  X.EmployeeMasterID = EM.EmployeeMasterID
   115	                                 AND  X.Status = 1)
   116	            ORDER BY EM.Code";
   117	
   118	        using (var cmd = new SqlCommand(sql, conn, tx))
   119	        {
   120	            cmd.Parameters.AddWithValue("@CompanyID", companyId);
   121	            cmd.Parameters.AddWithValue("@Epoch", EpochDate);
   122	            var dt = new DataTable();
   123	            using (var da = new SqlDataAdapter(cmd)) da.Fill(dt);
   124	            return dt;
   125	        }
   126	    }
   127	
   128	    /// <summary>
   129	    /// Opens the exit: header snapshot plus the five clearance rows, then evaluates
   130	    /// completeness so the verdict is right from the first render. Caller owns the
   131	    /// transaction.
   132	    /// </summary>
   133	    public static long CreateExit(SqlConnection conn, SqlTransaction tx, long employeeId,
   134	                                 long companyId, int userId, string systemName)
   135	    {
   136	        if (employeeId <= 0) throw new ArgumentException("employeeId is required.", "employeeId");
   137	
   138	        string exitNo = NextExitNo(conn, tx, DateTime.Today.Year);
   139	        long exitId;
   140	
   141	        using (var cmd = new SqlCommand(@"
   142	            INSERT INTO dbo.HR_ExitFormality
   143	                (ExitNo, EmployeeMasterID, ResignDate, LastWorkingDate, InterviewStatus,
   144	                 CategoryMasterID, BranchMasterID, CompanyMasterID, IsComplete, Status,
   145	                 EntryUserMasterID, EntryUserDateTime, SystemName)
   146	            SELECT @ExitNo, EM.EmployeeMasterID,
   147	                   NULLIF(EM.ResignDate, @Epoch), NULLIF(EM.DateOfLeft, @Epoch), @Pending,
   148	                   EM.CategoryMasterID, EM.BranchMasterID, @CompanyID, 0, 1,
   149	                   @UserID, GETDATE(), @SystemName
   150	            FROM   dbo.HR_EmployeeMaster EM
   151	            WHERE  EM.EmployeeMasterID = @EmpID;
   152	            SELECT CAST(SCOPE_IDENTITY() AS bigint);", conn, tx))
   153	        {
   154	            cmd.Parameters.AddWithValue("@ExitNo", exitNo);
   155	            cmd.Parameters.AddWithValue("@Epoch", EpochDate);
   156	            cmd.Parameters.AddWithValue("@Pending", InterviewPending);
   157	            cmd.Parameters.AddWithValue("@CompanyID", companyId);
   158	            cmd.Parameters.AddWithValue("@UserID", userId);
   159	            cmd.Parameters.AddWithValue("@SystemName", Trunc(systemName, 50));
   160	            cmd.Parameters.AddWithValue("@EmpID", employeeId);
   161	
   162	            object idObj = cmd.ExecuteScalar();
   163	            if (idObj == null || idObj == DBNull.Value)
   164	                throw new InvalidOperationException(
   165	                    "Employee " + employeeId + " was not found, so no exit record was created.");
   166	
   167	            exitId = Convert.ToInt64(idObj);
   168	        }
   169	
   170	        SeedClearances(conn, tx, exitId);
   171	        Evaluate(conn, tx, exitId);
   172	        return exitId;
   173	    }
   174	
   175	    /// <summary>Adds any clearance row the exit is missing. Never overwrites a department's
   176	    /// answer, so it is safe to re-run.</summary>
   177	    public static int SeedClearances(SqlConnection conn, SqlTransaction tx, long exitId)
   178	    {
   179	        int added = 0;
   180	
   181	        foreach (ClearanceDepartment d in Departments())
   182	        {
   183	            using (var cmd = new SqlCommand(@"
   184	                INSERT INTO dbo.HR_ExitClearance
   185	                    (ExitFormalityID, DepartmentCode, DepartmentName, ChecklistHint,
   186	                     ClearanceStatus, SortOrder)
   187	                SELECT @ExitID, @Code, @Name, @Hint, @Pending, @Sort
   188	                WHERE  NOT EXISTS (SELECT 1 FROM dbo.HR_ExitClearance
   189	                                   WHERE ExitFormalityID = @ExitID AND DepartmentCode = @Code);", conn, tx))
   190	            {
   191	                cmd.Parameters.AddWithValue("@ExitID", exitId);
   192	                cmd.Parameters.AddWithValue("@Code", d.Code);
   193	                cmd.Parameters.AddWithValue("@Name", d.Name);
   194	                cmd.Parameters.AddWithValue("@Hint", d.Hint);
   195	                cmd.Parameters.AddWithValue("@Pending", ClearancePending);
   196	                cmd.Parameters.AddWithValue("@Sort", d.SortOrder);
   197	                added += cmd.ExecuteNonQuery();
   198	            }
   199	        }
   200	
   201	        return added;
   202	    }
   203	
   204	    // -------------------------------------------------------------------------
   205	    //  Outstanding assets — read from the Assets module
   206	    // -------------------------------------------------------------------------
   207	
   208	    /// <summary>
   209	    /// What the employee still holds: quantity issued on approved issues minus the quantity
   210	    /// returned on ACTIVE returns. Never IsReturned, which is a derived cache, and never a
   211	    /// soft-deleted return, which would otherwise keep counting for ever.
   212	    ///
   213	    /// Fine from HR_AssetReturnDetail is surfaced as DamageFine so the exit screen can show
   214	    /// a damage charge that has already been recorded against a return.
   215	    /// </summary>
   216	    public static DataTable OutstandingAssets(SqlConnection conn, SqlTransaction tx, long exitId)
   217	    {
   218	        const string sql = @"
   219	            SELECT AI.IssueNo,
   220	                   AID.ID                AS IssueDetailID,
   221	                   ISNULL(AID.AssetName, '')  AS AssetName,
   222	                   ISNULL(AID.SerialNo, '')   AS SerialNo,
   223	                   AI.IssueDate,
   224	                   ISNULL(AID.QtyIssued, 0)   AS QtyIssued,
   225	                   ISNULL(Ret.QtyReturned, 0) AS QtyReturned,
   226	                   ISNULL(AID.QtyIssued, 0) - ISNULL(Ret.QtyReturned, 0) AS Balance,
   227	                   ISNULL(Ret.DamageFine, 0)  AS DamageFine,
   228	                   ISNULL(Ret.LastCondition, '') AS LastCondition
   229	            FROM   dbo.HR_ExitFormality X
   230	            INNER  JOIN dbo.HR_AssetIssue AI
   231	                   ON  AI.EmployeeMasterID = X.EmployeeMasterID
   232	                   AND AI.Status = 1
   233	                   AND AI.ApprovalStatus = 'Approved'
   234	            INNER  JOIN dbo.HR_AssetIssueDetail AID ON AID.IssueID = AI.ID
   235	            OUTER  APPLY (SELECT SUM(ARD.Qty) AS QtyReturned,
   236	                                 SUM(ISNULL(ARD.Fine, 0)) AS DamageFine,
   237	                                 MAX(ARD.Condition) AS LastCondition
   238	                          FROM   dbo.HR_AssetReturnDetail ARD
   239	                          INNER  JOIN dbo.HR_AssetReturn AR ON AR.ID = ARD.ReturnID
   240	                          WHERE  ARD.IssueDetailID = AID.ID AND AR.Status = 1) Ret
   241	            WHERE  X.ExitFormalityID = @ExitID
   242	            ORDER  BY AI.IssueNo, AID.ID";
   243	
   244	        using (var cmd = new SqlCommand(sql, conn, tx))
   245	        {
   246	            cmd.Parameters.AddWithValue("@ExitID", exitId);
   247	            var dt = new DataTable();
   248	            using (var da = new SqlDataAdapter(cmd)) da.Fill(dt);
   249	            return dt;
   250	        }
   251	    }
   252	
   253	    // -------------------------------------------------------------------------
   254	    //  Completeness
   255	    // -------------------------------------------------------------------------
   256	
   257	    /// <summary>
   258	    /// Recomputes the three verdicts and the block reason, cached on the header so the F&amp;F
   259	    /// eligibility query and the list grid do not re-walk clearances and asset balances for
   260	    /// every row.
   261	    ///
   262	    /// The reason names the FIRST thing outstanding, in the order a user would work through
   263	    /// it, which is what makes the message actionable rather than a count of failures.
   264	    /// Returns true when the exit is complete.
   265	    /// </summary>
   266	    public static bool Evaluate(SqlConnection conn, SqlTransaction tx, long exitId)
   267	    {
   268	        // -- interview --------------------------------------------------------
   269	        string interviewStatus;
   270	        using (var cmd = new SqlCommand(
   271	            "SELECT ISNULL(InterviewStatus, '') FROM dbo.HR_ExitFormality WHERE ExitFormalityID = @Id", conn, tx))
   272	        {
   273	            cmd.Parameters.AddWithValue("@Id", exitId);
   274	            interviewStatus = Convert.ToString(cmd.ExecuteScalar());
   275	        }
   276	
   277	        // Completed, Not Available and Skipped all COUNT as done: an employee who walks out
   278	        // cannot be interviewed, and blocking their settlement on it for ever would be
   279	        // punishing them for HR's process.
   280	        bool interviewDone =
   281	            interviewStatus == InterviewCompleted ||
   282	            interviewStatus == InterviewUnavailable ||
   283	            interviewStatus == InterviewSkipped;
   284	
   285	        // -- assets -----------------------------------------------------------
   286	        decimal assetBalance = 0m;
   287	        using (var cmd = new SqlCommand(@"
   288	            SELECT ISNULL(SUM(ISNULL(AID.QtyIssued,0) - ISNULL(Ret.QtyReturned,0)), 0)
   289	            FROM   dbo.HR_ExitFormality X
   290	            INNER  JOIN dbo.HR_AssetIssue AI
   291	                   ON  AI.EmployeeMasterID = X.EmployeeMasterID
   292	                   AND AI.Status = 1 AND AI.ApprovalStatus = 'Approved'
   293	            INNER  JOIN dbo.HR_AssetIssueDetail AID ON AID.IssueID = AI.ID
   294	            OUTER  APPLY (SELECT SUM(ARD.Qty) AS QtyReturned
   295	                          FROM   dbo.HR_AssetReturnDetail ARD
   296	                          INNER  JOIN dbo.HR_AssetReturn AR ON AR.ID = ARD.ReturnID
   297	                          WHERE  ARD.IssueDetailID = AID.ID AND AR.Status = 1) Ret
   298	            WHERE  X.ExitFormalityID = @Id", conn, tx))
   299	        {
   300	            cmd.Parameters.AddWithValue("@Id", exitId);
   301	            object value = cmd.ExecuteScalar();
   302	            if (value != null && value != DBNull.Value) assetBalance = Convert.ToDecimal(value);
   303	        }
   304	        bool assetsDone = (assetBalance <= 0);
   305	
   306	        // -- clearances -------------------------------------------------------
   307	        //
   308	        // A department has ANSWERED when it is either Cleared or has Raised an Objection.
   309	        // Only Pending blocks.
   310	        //
   311	        // An objection deliberately does NOT block: raising one with an amount is how a due
   312	        // gets recorded, and PushDuesToCase then carries it into the settlement as a
   313	        // recovery. Treating an objection as a blocker would be self-defeating - the case
   314	        // could never be created, so the recovery could never be collected, and the only way
   315	        // to settle anybody would be to withdraw the objection and lose the money.
   316	        int unanswered = 0;
   317	        string firstOutstanding = null;
   318	        decimal totalDues = 0m;
   319	
   320	        using (var cmd = new SqlCommand(@"
   321	            SELECT COUNT(*)
   322	            FROM   dbo.HR_ExitClearance
   323	            WHERE  ExitFormalityID = @Id AND ClearanceStatus = @Pending", conn, tx))
   324	        {
   325	            cmd.Parameters.AddWithValue("@Id", exitId);
   326	            cmd.Parameters.AddWithValue("@Pending", ClearancePending);
   327	            unanswered = Convert.ToInt32(cmd.ExecuteScalar());
   328	        }
   329	
   330	        if (unanswered > 0)
   331	        {
   332	            using (var cmd = new SqlCommand(@"
   333	                SELECT TOP 1 DepartmentName + ' has not responded yet.'
   334	                FROM   dbo.HR_ExitClearance
   335	                WHERE  ExitFormalityID = @Id AND ClearanceStatus = @Pending
   336	                ORDER  BY SortOrder, ExitClearanceID", conn, tx))
   337	            {
   338	                cmd.Parameters.AddWithValue("@Id", exitId);
   339	                cmd.Parameters.AddWithValue("@Pending", ClearancePending);
   340	                object value = cmd.ExecuteScalar();
   341	                if (value != null && value != DBNull.Value) firstOutstanding = Convert.ToString(value);
   342	            }
   343	        }
   344	
   345	        using (var cmd = new SqlCommand(
   346	            "SELECT ISNULL(SUM(DuesAmount), 0) FROM dbo.HR_ExitClearance WHERE ExitFormalityID = @Id",
   347	            conn, tx))
   348	        {
   349	            cmd.Parameters.AddWithValue("@Id", exitId);
   350	            totalDues = Convert.ToDecimal(cmd.ExecuteScalar());
   351	        }
   352	
   353	        bool clearanceDone = (unanswered == 0);
   354	        bool complete = interviewDone && assetsDone && clearanceDone;
   355	
   356	        // Ordered the way a user works through the stage.
   357	        string blockReason = null;
   358	        if (!interviewDone)
   359	            blockReason = "Exit interview is " +
   360	                (string.IsNullOrEmpty(interviewStatus) ? "not recorded" : interviewStatus.ToLowerInvariant()) + ".";
   361	        else if (!assetsDone)
   362	            blockReason = assetBalance.ToString("0.##") + " asset item(s) are still with the employee. "
   363	                        + "Record the return in Assets ▸ Asset Return.";
   364	        else if (!clearanceDone)
   365	            blockReason = firstOutstanding
   366	                        + (unanswered > 1 ? " (" + unanswered + " departments yet to respond)" : string.Empty);
   367	
   368	        using (var cmd = new SqlCommand(@"
   369	            UPDATE dbo.HR_ExitFormality
   370	            SET    AssetReturnComplete = @Assets,
   371	                   ClearanceComplete   = @Clearance,
   372	                   IsComplete          = @Complete,
   373	                   BlockReason         = @Reason,
   374	                   TotalDues           = @Dues,
   375	                   CompletedOn         = CASE WHEN @Complete = 1 AND CompletedOn IS NULL
   376	                                              THEN GETDATE() ELSE CompletedOn END
   377	            WHERE  ExitFormalityID = @Id", conn, tx))
   378	        {
   379	            cmd.Parameters.AddWithValue("@Assets", assetsDone);
   380	            cmd.Parameters.AddWithValue("@Clearance", clearanceDone);
   381	            cmd.Parameters.AddWithValue("@Complete", complete);
   382	            cmd.Parameters.AddWithValue("@Reason", (object)blockReason ?? DBNull.Value);
   383	            cmd.Parameters.AddWithValue("@Dues", totalDues);
   384	            cmd.Parameters.AddWithValue("@Id", exitId);
   385	            cmd.ExecuteNonQuery();
   386	        }
   387	
   388	        return complete;
   389	    }
   390	
   391	    // -------------------------------------------------------------------------
   392	    //  Handing over to F&F
   393	    // -------------------------------------------------------------------------
   394	
   395	    /// <summary>
   396	    /// The completed exit for an employee, or 0. This is what the F&amp;F eligibility gate
   397	    /// asks about.
   398	    /// </summary>
   399	    public static long CompletedExitFor(SqlConnection conn, SqlTransaction tx, long employeeId)
   400	    {
   401	        using (var cmd = new SqlCommand(@"
   402	            SELECT TOP 1 ExitFormalityID
   403	            FROM   dbo.HR_ExitFormality
   404	            WHERE  EmployeeMasterID = @Emp AND Status = 1 AND IsComplete = 1
   405	            ORDER  BY ExitFormalityID DESC", conn, tx))
   406	        {
   407	            cmd.Parameters.AddWithValue("@Emp", employeeId);
   408	            object value = cmd.ExecuteScalar();
   409	            return (value == null || value == DBNull.Value) ? 0 : Convert.ToInt64(value);
   410	        }
   411	    }
   412	
   413	    /// <summary>
   414	    /// Copies every department objection carrying an amount into the F&amp;F case as a
   415	    /// recovery, so a due raised at clearance cannot be forgotten at settlement.
   416	    ///
   417	    /// Guarded by NOT EXISTS on the same department, so re-running adds nothing and — the
   418	    /// point — does not resurrect a row somebody has since Waived on the F&amp;F side.
   419	    /// </summary>
   420	    public static int PushDuesToCase(SqlConnection conn, SqlTransaction tx, long exitId, long caseId,
   421	                                     int userId, string systemName)
   422	    {
   423	        using (var cmd = new SqlCommand(@"
   424	            INSERT INTO dbo.HR_FNFRecovery
   425	                (FNFSettlementID, ClearanceDepartment, DuesType, Description, Amount,
   426	                 RecoveryStatus, Status, EntryUserMasterID, EntryUserDateTime, SystemName)
   427	            SELECT @CaseID, C.DepartmentCode, 'Other',
   428	                   C.DepartmentName + ' objection: '
   429	                     + ISNULL(NULLIF(LTRIM(RTRIM(C.DuesDescription)), ''),
   430	                              ISNULL(NULLIF(LTRIM(RTRIM(C.Remarks)), ''), 'dues raised at exit clearance')),
   431	                   C.DuesAmount, 'Confirmed', 1, @UserID, GETDATE(), @SystemName
   432	            FROM   dbo.HR_ExitClearance C
   433	            WHERE  C.ExitFormalityID = @ExitID
   434	              AND  C.DuesAmount > 0
   435	              AND  NOT EXISTS (SELECT 1 FROM dbo.HR_FNFRecovery R
   436	                               WHERE R.FNFSettlementID = @CaseID
   437	                                 AND R.ClearanceDepartment = C.DepartmentCode
   438	                                 AND R.DuesType = 'Other');", conn, tx))
   439	        {
