   257	    /// <summary>
   258	    /// Recomputes the three verdicts and the block reason, cached on the header so the F&amp;F
   259	    /// eligibility query and the list grid do not re-walk clearances and asset balances for
   260	    /// every row.
   261	    ///
   262	    /// The reason names the FIRST thing outstanding, in the order a user would work through
   263	    /// it, which is what makes the message actionable rather than a count of failures.
   264	    /// Returns true when the exit is complete.
   265	    /// </summary>
   266	    public static bool Evaluate(SqlConnection conn, SqlTransaction tx, long exitId)
   267	    {
   268	        // -- interview --------------------------------------------------------
   269	        string interviewStatus;
   270	        using (var cmd = new SqlCommand(
   271	            "SELECT ISNULL(InterviewStatus, '') FROM dbo.HR_ExitFormality WHERE ExitFormalityID = @Id", conn, tx))
   272	        {
   273	            cmd.Parameters.AddWithValue("@Id", exitId);
   274	            interviewStatus = Convert.ToString(cmd.ExecuteScalar());
   275	        }
   276	
   277	        // Completed, Not Available and Skipped all COUNT as done: an employee who walks out
   278	        // cannot be interviewed, and blocking their settlement on it for ever would be
   279	        // punishing them for HR's process.
   280	        bool interviewDone =
   281	            interviewStatus == InterviewCompleted ||
   282	            interviewStatus == InterviewUnavailable ||
   283	            interviewStatus == InterviewSkipped;
   284	
   285	        // -- assets -----------------------------------------------------------
   286	        decimal assetBalance = 0m;
   287	        using (var cmd = new SqlCommand(@"
   288	            SELECT ISNULL(SUM(ISNULL(AID.QtyIssued,0) - ISNULL(Ret.QtyReturned,0)), 0)
   289	            FROM   dbo.HR_ExitFormality X
   290	            INNER  JOIN dbo.HR_AssetIssue AI
   291	                   ON  AI.EmployeeMasterID = X.EmployeeMasterID
   292	                   AND AI.Status = 1 AND AI.ApprovalStatus = 'Approved'
   293	            INNER  JOIN dbo.HR_AssetIssueDetail AID ON AID.IssueID = AI.ID
   294	            OUTER  APPLY (SELECT SUM(ARD.Qty) AS QtyReturned
   295	                          FROM   dbo.HR_AssetReturnDetail ARD
   296	                          INNER  JOIN dbo.HR_AssetReturn AR ON AR.ID = ARD.ReturnID
   297	                          WHERE  ARD.IssueDetailID = AID.ID AND AR.Status = 1) Ret
   298	            WHERE  X.ExitFormalityID = @Id", conn, tx))
   299	        {
   300	            cmd.Parameters.AddWithValue("@Id", exitId);
   301	            object value = cmd.ExecuteScalar();
   302	            if (value != null && value != DBNull.Value) assetBalance = Convert.ToDecimal(value);
   303	        }
   304	        bool assetsDone = (assetBalance <= 0);
   305	
   306	        // -- clearances -------------------------------------------------------
   307	        //
   308	        // A department has ANSWERED when it is either Cleared or has Raised an Objection.
   309	        // Only Pending blocks.
   310	        //
   311	        // An objection deliberately does NOT block: raising one with an amount is how a due
   312	        // gets recorded, and PushDuesToCase then carries it into the settlement as a
   313	        // recovery. Treating an objection as a blocker would be self-defeating - the case
   314	        // could never be created, so the recovery could never be collected, and the only way
   315	        // to settle anybody would be to withdraw the objection and lose the money.
   316	        int unanswered = 0;
   317	        string firstOutstanding = null;
   318	        decimal totalDues = 0m;
   319	
   320	        using (var cmd = new SqlCommand(@"
   321	            SELECT COUNT(*)
   322	            FROM   dbo.HR_ExitClearance
   323	            WHERE  ExitFormalityID = @Id AND ClearanceStatus = @Pending", conn, tx))
   324	        {
   325	            cmd.Parameters.AddWithValue("@Id", exitId);
   326	            cmd.Parameters.AddWithValue("@Pending", ClearancePending);
   327	            unanswered = Convert.ToInt32(cmd.ExecuteScalar());
   328	        }
   329	
   330	        if (unanswered > 0)
   331	        {
   332	            using (var cmd = new SqlCommand(@"
   333	                SELECT TOP 1 DepartmentName + ' has not responded yet.'
   334	                FROM   dbo.HR_ExitClearance
   335	                WHERE  ExitFormalityID = @Id AND ClearanceStatus = @Pending
   336	                ORDER  BY SortOrder, ExitClearanceID", conn, tx))
   337	            {
   338	                cmd.Parameters.AddWithValue("@Id", exitId);
   339	                cmd.Parameters.AddWithValue("@Pending", ClearancePending);
   340	                object value = cmd.ExecuteScalar();
   341	                if (value != null && value != DBNull.Value) firstOutstanding = Convert.ToString(value);
   342	            }
   343	        }
   344	
   345	        using (var cmd = new SqlCommand(
   346	            "SELECT ISNULL(SUM(DuesAmount), 0) FROM dbo.HR_ExitClearance WHERE ExitFormalityID = @Id",
   347	            conn, tx))
