 38	    public async Task<List<EmployeeNeedingExitModel>> GetEmployeesNeedingExitAsync(long companyId)
 39	    {
 40	        const string sql = @"
 41	            SELECT EM.EmployeeMasterID AS EmployeeMasterId,
 42	                   LTRIM(ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.FirstName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.FatherName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.LastName)),''), ''))
 43	                       + ' (' + ISNULL(EM.Code, '') + ')' AS Name
 44	            FROM   HR_EmployeeMaster EM
 45	            WHERE  EM.Status = 1
 46	              AND  EM.CompanyMasterID = @CompanyId
 47	              AND  ( (EM.ResignDate IS NOT NULL AND EM.ResignDate > @Epoch)
 48	                  OR (EM.DateOfLeft IS NOT NULL AND EM.DateOfLeft > @Epoch) )
 49	              AND  NOT EXISTS (SELECT 1 FROM HR_ExitFormality X
 50	                               WHERE  X.EmployeeMasterID = EM.EmployeeMasterID AND X.Status = 1)
 51	            ORDER BY EM.Code";
 52	
 53	        var res = await _repo.QueryAsync<EmployeeNeedingExitModel>(sql, new { CompanyId = companyId, Epoch = EpochDate });
 54	        return res.ToList();
 55	    }
