 63	            SELECT X.ExitFormalityID AS ExitFormalityId, X.ExitNo, X.LastWorkingDate, X.InterviewStatus,
 64	                   ISNULL(X.TotalDues, 0) AS TotalDues,
 65	                   LTRIM(ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.FirstName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.FatherName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.LastName)),''), '')) AS EmployeeName,
 66	                   ISNULL(EM.Code, '') AS EmployeeCode,
