100	            LEFT   JOIN HR_DepartmentMaster D  ON D.DepartmentMasterID  = EM.DepartmentMasterID
101	            LEFT   JOIN HR_DesignationMaster G ON G.DesignationMasterID = EM.DesignationMasterID
102	            LEFT   JOIN HR_EmployeeMaster    MG ON MG.EmployeeMasterID  = EM.ReportingPersonID
