169	    private async Task<int> SeedClearancesInternalAsync(long exitId)
170	    {
171	        var added = 0;
172	        const string sql = @"
173	            INSERT INTO HR_ExitClearance
174	                (ExitFormalityID, DepartmentCode, DepartmentName, ChecklistHint, ClearanceStatus, SortOrder)
175	            SELECT @ExitId, @Code, @Name, @Hint, 'Pending', @Sort
176	            WHERE  NOT EXISTS (SELECT 1 FROM HR_ExitClearance
177	                               WHERE ExitFormalityID = @ExitId AND DepartmentCode = @Code)";
178	
179	        var checklist = await GetClearanceChecklistAsync(exitId);
180	
181	        foreach (var (code, name, hint, sortOrder) in checklist)
182	            added += await _repo.ExecuteAsync(sql, new { ExitId = exitId, Code = code, Name = name, Hint = hint, Sort = sortOrder });
183	
184	        return added;
185	    }
