187	    /// <summary>
188	    /// The department checkpoints for one exit, resolved from this exit's own company: its
189	    /// admin-configured HR_FNFClearanceDepartment selection if it has ever saved one (even an
190	    /// empty one - see FnfConfigRepository.ReplaceClearanceDepartmentsAsync), else the fixed
191	    /// legacy checklist every company used before this config screen existed. Reporting Manager
192	    /// clearance is appended unconditionally - it is not a department.
193	    /// </summary>
194	    private async Task<List<(string Code, string Name, string Hint, int SortOrder)>> GetClearanceChecklistAsync(long exitId)
195	    {
196	        const string configSql = @"
197	            SELECT ISNULL(F.UseCustomClearanceDepartments, 0) AS UseCustom, X.CompanyMasterID AS CompanyMasterId
198	            FROM   HR_ExitFormality X
199	            LEFT   JOIN HR_FNFConfig F ON F.CompanyMasterID = X.CompanyMasterID AND F.Status = 1
200	            WHERE  X.ExitFormalityID = @ExitId";
201	
202	        var config = await _repo.QueryFirstOrDefaultAsync<(bool UseCustom, long CompanyMasterId)>(configSql, new { ExitId = exitId });
203	
204	        List<(string Code, string Name, string Hint, int SortOrder)> departments;
205	
206	        if (config.UseCustom)
207	        {
208	            const string configuredSql = @"
209	                SELECT D.DepartmentCode AS Code, D.DepartmentName AS Name,
210	                       ISNULL(C.ChecklistHint, '') AS Hint, C.SortOrder
211	                FROM   HR_FNFClearanceDepartment C
212	                INNER  JOIN HR_DepartmentMaster D ON D.DepartmentMasterID = C.DepartmentMasterID
213	                WHERE  C.CompanyMasterID = @CompanyMasterId
214	                ORDER  BY C.SortOrder, C.FNFClearanceDepartmentID";
215	
216	            departments = (await _repo.QueryAsync<(string, string, string, int)>(configuredSql,
217	                new { config.CompanyMasterId })).ToList();
218	        }
219	        else
220	        {
221	            departments = FallbackDepartments.ToList();
222	        }
223	
224	        departments.Add(ManagerClearance);
225	        return departments;
226	    }
