228	    public async Task<List<OutstandingAssetModel>> GetOutstandingAssetsAsync(long exitId)
229	    {
230	        const string sql = @"
231	            SELECT AI.IssueNo,
232	                   AID.ID                AS IssueDetailId,
233	                   ISNULL(AID.AssetName, '')  AS AssetName,
234	                   ISNULL(AID.SerialNo, '')   AS SerialNo,
235	                   AI.IssueDate,
236	                   ISNULL(AID.QtyIssued, 0)   AS QtyIssued,
237	                   ISNULL(Ret.QtyReturned, 0) AS QtyReturned,
238	                   ISNULL(AID.QtyIssued, 0) - ISNULL(Ret.QtyReturned, 0) AS Balance,
239	                   ISNULL(Ret.DamageFine, 0)  AS DamageFine,
240	                   ISNULL(Ret.LastCondition, '') AS LastCondition
241	            FROM   HR_ExitFormality X
242	            INNER  JOIN HR_AssetIssue AI
243	                   ON  AI.EmployeeMasterID = X.EmployeeMasterID
244	                   AND AI.Status = 1
245	                   AND AI.ApprovalStatus = 'Approved'
246	            INNER  JOIN HR_AssetIssueDetail AID ON AID.IssueID = AI.ID
247	            OUTER  APPLY (SELECT SUM(ARD.Qty) AS QtyReturned,
248	                                 SUM(ISNULL(ARD.Fine, 0)) AS DamageFine,
249	                                 MAX(ARD.Condition) AS LastCondition
250	                          FROM   HR_AssetReturnDetail ARD
251	                          INNER  JOIN HR_AssetReturn AR ON AR.ID = ARD.ReturnID
252	                          WHERE  ARD.IssueDetailID = AID.ID AND AR.Status = 1) Ret
253	            WHERE  X.ExitFormalityID = @ExitId
254	            ORDER  BY AI.IssueNo, AID.ID";
255	
256	        var res = await _repo.QueryAsync<OutstandingAssetModel>(sql, new { ExitId = exitId });
257	        return res.ToList();
258	    }
