108	    public async Task<long> CreateExitAsync(long employeeId, long companyId, long userId)
109	    {
110	        await _tx.BeginTransactionAsync();
111	        try
112	        {
113	            var prefix = $"EXIT-{DateTime.Today.Year}-";
114	            const string nextNoSql = @"
115	                SELECT MAX(CAST(RIGHT(ExitNo, 5) AS int))
116	                FROM   HR_ExitFormality WITH (UPDLOCK, HOLDLOCK)
117	                WHERE  ExitNo LIKE @Prefix + '[0-9][0-9][0-9][0-9][0-9]'";
118	            var max = await _repo.ExecuteScalarAsync<int?>(nextNoSql, new { Prefix = prefix });
119	            var exitNo = prefix + ((max ?? 0) + 1).ToString("00000");
120	
121	            const string insertSql = @"
122	                INSERT INTO HR_ExitFormality
123	                    (ExitNo, EmployeeMasterID, ResignDate, LastWorkingDate, InterviewStatus,
124	                     CategoryMasterID, BranchMasterID, CompanyMasterID, IsComplete, Status,
125	                     EntryUserMasterID, EntryUserDateTime)
126	                SELECT @ExitNo, EM.EmployeeMasterID,
127	                       NULLIF(EM.ResignDate, @Epoch), NULLIF(EM.DateOfLeft, @Epoch), 'Pending',
128	                       EM.CategoryMasterID, EM.BranchMasterID, @CompanyId, 0, 1,
129	                       @UserId, @Now
130	                FROM   HR_EmployeeMaster EM
131	                WHERE  EM.EmployeeMasterID = @EmployeeId;
132	                SELECT CAST(SCOPE_IDENTITY() AS bigint);";
133	
134	            var exitId = await _repo.ExecuteScalarAsync<long?>(insertSql, new
135	            {
136	                ExitNo = exitNo, Epoch = EpochDate, CompanyId = companyId, UserId = userId,
137	                Now = DateTime.Now, EmployeeId = employeeId,
138	            });
139	            if (exitId is null or 0)
140	                throw new InvalidOperationException($"Employee {employeeId} was not found, so no exit record was created.");
141	
142	            await SeedClearancesInternalAsync(exitId.Value);
143	            await _tx.CommitAsync();
144	            return exitId.Value;
145	        }
146	        catch
147	        {
148	            await _tx.RollbackAsync();
149	            throw;
150	        }
151	    }
