44	    44	    /// <summary>SystemName column widths vary across this schema (20 to 128) and 2014 does
45	    45	    /// not name the column in a truncation error, so cap it.</summary>
46	    46	    private static string HostNameCapped()
47	    47	    {
48	    48	        string name = null;
49	    49	        try { name = System.Net.Dns.GetHostName(); } catch { /* not fatal */ }
50	    50	        if (string.IsNullOrEmpty(name)) return string.Empty;
51	    51	        return name.Length > 50 ? name.Substring(0, 50) : name;
52	    52	    }
