138	   138	    private DataTable LoadExits()
139	   139	    {
140	   140	        // An exit record carries the employee's own words from their interview. An admin sees
141	   141	        // the company's exits; anyone else sees only the ones they are working on. Scoped in
142	   142	        // the single query the grid runs, so paging and filtering cannot widen it - the same
143	   143	        // rule the settlement list uses.
144	   144	        string scope = RoleHelper.IsAdmin(Session["UserRole"])
145	   145	            ? string.Empty
146	   146	            : " AND (X.InterviewByUserMasterID = @UserID OR X.EntryUserMasterID = @UserID) ";
147	   147	
148	   148	        string sql = @"
149	   149	            SELECT X.ExitFormalityID, X.ExitNo, X.LastWorkingDate, X.InterviewStatus,
150	   150	                   ISNULL(X.TotalDues, 0) AS TotalDues,
151	   151	                   LTRIM(ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.FirstName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.FatherName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.LastName)),''), '')) AS EmployeeName,
152	   152	                   ISNULL(EM.Code, '') AS EmployeeCode,
153	   153	                   CASE WHEN ISNULL(X.ClearanceComplete, 0) = 1 THEN 'All answered' ELSE 'Waiting' END AS ClearanceText,
154	   154	                   CASE WHEN X.IsComplete = 1 THEN 'Complete - F&F can be raised'
155	   155	                        ELSE ISNULL(X.BlockReason, 'Not checked') END AS StatusText,
156	   156	                   X.IsComplete
157	   157	            FROM   dbo.HR_ExitFormality X
158	   158	            LEFT   JOIN dbo.HR_EmployeeMaster EM ON EM.EmployeeMasterID = X.EmployeeMasterID
159	   159	            WHERE  X.Status = 1 AND X.CompanyMasterID = @CompanyID " + scope + @"
160	   160	            ORDER  BY X.ExitFormalityID DESC";
161	   161	
162	   162	        var table = new DataTable();
163	   163	        try
164	   164	        {
165	   165	            using (SqlConnection conn = CreateConnection())
166	   166	            using (var cmd = new SqlCommand(sql, conn))
167	   167	            {
168	   168	                cmd.Parameters.AddWithValue("@CompanyID", CompanyId);
169	   169	                cmd.Parameters.AddWithValue("@UserID", UserId);
170	   170	                using (var da = new SqlDataAdapter(cmd)) da.Fill(table);
171	   171	            }
172	   172	        }
173	   173	        catch (Exception ex)
174	   174	        {
175	   175	            ErrorLogHelper.Log(ex, "ExitFormality.LoadExits");
176	   176	        }
177	   177	        return table;
178	   178	    }
