201	   201	    // -- Panel dispatch -------------------------------------------------------
202	   202	
203	   203	    protected void ExPanel_Callback(object sender, CallbackEventArgsBase e)
204	   204	    {
205	   205	        string[] parts = (e.Parameter ?? string.Empty).Split('|');
206	   206	        if (parts.Length < 2) return;
207	   207	
208	   208	        string action = parts[0];
209	   209	        long id;
210	   210	        long.TryParse(parts[1], out id);
211	   211	
212	   212	        try
213	   213	        {
214	   214	            switch (action)
215	   215	            {
216	   216	                case "New":      HandleNew();      break;
217	   217	                case "Create":   HandleCreate();   break;
218	   218	                case "Load":     LoadExit(id);     break;
219	   219	                case "Save":     HandleSave();     break;
220	   220	                case "Recheck":  HandleRecheck();  break;
221	   221	                case "MakeCase": HandleMakeCase(); break;
222	   222	            }
223	   223	        }
224	   224	        catch (Exception ex)
225	   225	        {
226	   226	            ErrorLogHelper.Log(ex, "ExitFormality." + action);
227	   227	            ExPanel.JSProperties["cpMsg"] = ErrorLogHelper.FriendlyMessage;
228	   228	        }
229	   229	    }
