231	   231	    private void HandleNew()
232	   232	    {
233	   233	        CurrentExitId = 0;
234	   234	
235	   235	        txtExitNo.Text = string.Empty;
236	   236	        cmbEmployee.Value = null;
237	   237	        cmbEmployee.Enabled = true;
238	   238	        cmbInterviewStatus.Value = ExitFormalityService.InterviewPending;
239	   239	        dtInterview.Value = null;
240	   240	        cmbInterviewBy.Value = null;
241	   241	        cmbReason.Value = null;
242	   242	        memEmployeeFeedback.Text = string.Empty;
243	   243	        memManagerFeedback.Text = string.Empty;
244	   244	        litBanner.Text = string.Empty;
245	   245	
246	   246	        int waiting = LoadEmployeesNeedingExit();
247	   247	
248	   248	        if (waiting == 0)
249	   249	        {
250	   250	            litSnapshot.Text =
251	   251	                "<div class=\"ex-banner blocked\">Nobody in this company needs an exit record.</div>"
252	   252	              + "<div class=\"ex-kv\">The list only offers employees who have a <b>Date Of Resign</b> "
253	   253	              + "or a <b>Date Of Left</b> on their record and do not already have one. Set the "
254	   254	              + "resignation date in <b>Employee &#8594; Employee</b> first.</div>";
255	   255	        }
256	   256	        else
257	   257	        {
258	   258	            string count = waiting < 0
259	   259	                ? "The employee list could not be read - check HR_ErrorLog."
260	   260	                : waiting + " employee" + (waiting == 1 ? "" : "s") + " awaiting exit formality.";
261	   261	
262	   262	            litSnapshot.Text = "<div class=\"ex-kv\">" + HttpUtility.HtmlEncode(count)
263	   263	                + " Pick one and press <b>Open Exit</b>. Their dates, department and manager are "
264	   264	                + "copied from the employee record, and the five department clearance rows are "
265	   265	                + "created automatically.</div>";
266	   266	        }
267	   267	
268	   268	        ExPanel.JSProperties["cpCreating"] = "1";
269	   269	        ExPanel.JSProperties["cpComplete"] = "0";
270	   270	        ExPanel.JSProperties["cpNoEligible"] = (waiting == 0) ? "1" : "0";
271	   271	    }
272	   272	
273	   273	    private void HandleCreate()
274	   274	    {
275	   275	        if (cmbEmployee.Value == null)
276	   276	        {
277	   277	            ExPanel.JSProperties["cpMsg"] = "Pick the employee first.";
278	   278	            return;
279	   279	        }
280	   280	
281	   281	        long employeeId = Convert.ToInt64(cmbEmployee.Value);
282	   282	        long newId;
283	   283	
284	   284	        using (SqlConnection conn = CreateConnection())
285	   285	        {
286	   286	            conn.Open();
287	   287	            // One transaction: header, five clearance rows and the first verdict. An exit
288	   288	            // must never exist with a half-built clearance list.
289	   289	            using (SqlTransaction tx = conn.BeginTransaction())
290	   290	            {
291	   291	                try
292	   292	                {
293	   293	                    newId = ExitFormalityService.CreateExit(conn, tx, employeeId, CompanyId,
294	   294	                                                            UserId, HostNameCapped());
295	   295	                    tx.Commit();
296	   296	                }
297	   297	                catch
298	   298	                {
299	   299	                    try { tx.Rollback(); } catch { /* connection already gone */ }
300	   300	                    throw;
301	   301	                }
302	   302	            }
303	   303	        }
304	   304	
305	   305	        LoadExit(newId);
306	   306	        ExPanel.JSProperties["cpMsg"] = "Exit " + txtExitNo.Text + " opened.";
307	   307	    }
308	   308	
309	   309	    private void LoadExit(long id)
310	   310	    {
311	   311	        if (id <= 0) return;
312	   312	
313	   313	        const string sql = @"
314	   314	            SELECT X.*,
315	   315	                   LTRIM(ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.FirstName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.FatherName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.LastName)),''), '')) AS EmployeeName,
316	   316	                   ISNULL(EM.Code, '')           AS EmployeeCode,
317	   317	                   ISNULL(D.DepartmentName, '')  AS DepartmentName,
318	   318	                   ISNULL(G.DesignationName, '') AS DesignationName,
319	   319	                   LTRIM(ISNULL(' ' + NULLIF(LTRIM(RTRIM(MG.FirstName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(MG.LastName)),''), '')) AS ManagerName,
320	   320	                   NULLIF(EM.DateOfJoining, '1900-01-01') AS DateOfJoining,
321	   321	                   (SELECT COUNT(*) FROM dbo.HR_FNFSettlement F
322	   322	                    WHERE F.EmployeeMasterID = X.EmployeeMasterID AND F.Status = 1
323	   323	                      AND F.WorkflowStatus <> 'Cancelled')        AS ExistingCases
324	   324	            FROM   dbo.HR_ExitFormality X
325	   325	            LEFT   JOIN dbo.HR_EmployeeMaster    EM ON EM.EmployeeMasterID   = X.EmployeeMasterID
326	   326	            LEFT   JOIN dbo.HR_DepartmentMaster  D  ON D.DepartmentMasterID  = EM.DepartmentMasterID
327	   327	            LEFT   JOIN dbo.HR_DesignationMaster G  ON G.DesignationMasterID = EM.DesignationMasterID
328	   328	            LEFT   JOIN dbo.HR_EmployeeMaster    MG ON MG.EmployeeMasterID   = EM.ReportingPersonID
329	   329	            WHERE  X.ExitFormalityID = @Id";
330	   330	
331	   331	        DataRow row = null;
332	   332	        using (SqlConnection conn = CreateConnection())
333	   333	        using (var cmd = new SqlCommand(sql, conn))
334	   334	        {
335	   335	            cmd.Parameters.AddWithValue("@Id", id);
336	   336	            var dt = new DataTable();
337	   337	            using (var da = new SqlDataAdapter(cmd)) da.Fill(dt);
338	   338	            if (dt.Rows.Count > 0) row = dt.Rows[0];
339	   339	        }
340	   340	
341	   341	        if (row == null)
342	   342	        {
343	   343	            ExPanel.JSProperties["cpMsg"] = "That exit record no longer exists.";
344	   344	            ExPanel.JSProperties["cpReloadList"] = true;
345	   345	            return;
346	   346	        }
347	   347	
348	   348	        CurrentExitId = id;
349	   349	
350	   350	        txtExitNo.Text = Convert.ToString(row["ExitNo"]);
351	   351	
352	   352	        // The employee cannot be changed once the exit exists - the snapshot came from them.
353	   353	        cmbEmployee.Value = Convert.ToInt64(row["EmployeeMasterID"]);
354	   354	        cmbEmployee.Enabled = false;
355	   355	
356	   356	        cmbInterviewStatus.Value = Convert.ToString(row["InterviewStatus"]);
357	   357	        dtInterview.Value = NullIfDbNull(row["InterviewDate"]);
358	   358	        cmbInterviewBy.Value = NullIfDbNull(row["InterviewByUserMasterID"]);
359	   359	        cmbReason.Value = NullIfDbNull(row["ReasonForLeaving"]);
360	   360	        memEmployeeFeedback.Text = Convert.ToString(row["EmployeeFeedback"]);
361	   361	        memManagerFeedback.Text = Convert.ToString(row["ManagerFeedback"]);
362	   362	
363	   363	        litSnapshot.Text = BuildSnapshotHtml(row);
364	   364	        litBanner.Text = BuildBannerHtml(row);
365	   365	
366	   366	        AssetGrid.DataBind();
367	   367	        ClearanceGrid.DataBind();
368	   368	
369	   369	        bool complete = row["IsComplete"] != DBNull.Value && Convert.ToBoolean(row["IsComplete"]);
370	   370	        bool alreadyCased = Convert.ToInt32(row["ExistingCases"]) > 0;
371	   371	
372	   372	        ExPanel.JSProperties["cpCreating"] = "0";
373	   373	        // Offer Create F&F Case only when the exit is done AND no live case exists, so the
374	   374	        // button cannot make a second settlement for the same person.
375	   375	        ExPanel.JSProperties["cpComplete"] = (complete && !alreadyCased) ? "1" : "0";
376	   376	    }
