378	   378	    private static object NullIfDbNull(object value)
379	   379	    {
380	   380	        return (value == null || value == DBNull.Value) ? null : value;
381	   381	    }
382	   382	
383	   383	    private static string Cell(string label, object value)
384	   384	    {
385	   385	        string text = (value == null || value == DBNull.Value || Convert.ToString(value).Length == 0)
386	   386	            ? "<i style=\"color:#999\">not set</i>"
387	   387	            : HttpUtility.HtmlEncode(Convert.ToString(value));
388	   388	
389	   389	        return "<td style=\"padding:4px 14px 4px 0;white-space:nowrap\"><span style=\"color:#777\">" +
390	   390	               HttpUtility.HtmlEncode(label) + "</span><br /><b>" + text + "</b></td>";
391	   391	    }
392	   392	
393	   393	    private static string DateCell(string label, object value)
394	   394	    {
395	   395	        if (value == null || value == DBNull.Value) return Cell(label, null);
396	   396	        return Cell(label, Convert.ToDateTime(value).ToString("dd-MM-yyyy"));
397	   397	    }
398	   398	
399	   399	    private string BuildSnapshotHtml(DataRow row)
400	   400	    {
401	   401	        var sb = new System.Text.StringBuilder();
402	   402	        sb.Append("<table class=\"ex-kv\" style=\"border-collapse:collapse\"><tr>");
403	   403	        sb.Append(Cell("Employee", row["EmployeeName"]));
404	   404	        sb.Append(Cell("Code", row["EmployeeCode"]));
405	   405	        sb.Append(Cell("Department", row["DepartmentName"]));
406	   406	        sb.Append(Cell("Designation", row["DesignationName"]));
407	   407	        sb.Append(Cell("Manager", row["ManagerName"]));
408	   408	        sb.Append("</tr><tr>");
409	   409	        sb.Append(DateCell("Joining Date", row["DateOfJoining"]));
410	   410	        sb.Append(DateCell("Resignation Date", row["ResignDate"]));
411	   411	        sb.Append(DateCell("Last Working Day", row["LastWorkingDate"]));
412	   412	        sb.Append(Cell("Dues Raised", Convert.ToDecimal(row["TotalDues"]).ToString("n2")));
413	   413	        sb.Append(DateCell("Completed On", row["CompletedOn"]));
414	   414	        sb.Append("</tr></table>");
415	   415	        return sb.ToString();
416	   416	    }
417	   417	
418	   418	    /// <summary>
419	   419	    /// The verdict, plus a three-step indicator so it is obvious WHICH of the three parts is
420	   420	    /// holding things up rather than just that something is.
421	   421	    /// </summary>
422	   422	    private string BuildBannerHtml(DataRow row)
423	   423	    {
424	   424	        bool complete = row["IsComplete"] != DBNull.Value && Convert.ToBoolean(row["IsComplete"]);
425	   425	        bool assets = row["AssetReturnComplete"] != DBNull.Value && Convert.ToBoolean(row["AssetReturnComplete"]);
426	   426	        bool clearance = row["ClearanceComplete"] != DBNull.Value && Convert.ToBoolean(row["ClearanceComplete"]);
427	   427	
428	   428	        string status = Convert.ToString(row["InterviewStatus"]);
429	   429	        bool interview = status == ExitFormalityService.InterviewCompleted
430	   430	                      || status == ExitFormalityService.InterviewUnavailable
431	   431	                      || status == ExitFormalityService.InterviewSkipped;
432	   432	
433	   433	        string steps =
434	   434	            Step("Exit Interview", interview) +
435	   435	            Step("Asset Return", assets) +
436	   436	            Step("Department Clearance", clearance);
437	   437	
438	   438	        if (complete)
439	   439	        {
440	   440	            return "<div class=\"ex-banner ready\">Exit Formality complete &mdash; the F&amp;F case "
441	   441	                 + "can now be created.<div style=\"margin-top:6px\">" + steps + "</div></div>";
442	   442	        }
443	   443	
444	   444	        string reason = Convert.ToString(row["BlockReason"]);
445	   445	        if (string.IsNullOrEmpty(reason)) reason = "Not checked yet - press Re-check.";
446	   446	
447	   447	        return "<div class=\"ex-banner blocked\">Exit Formality not complete &mdash; "
448	   448	             + HttpUtility.HtmlEncode(reason)
449	   449	             + "<div style=\"margin-top:6px\">" + steps + "</div></div>";
450	   450	    }
451	   451	
452	   452	    private static string Step(string label, bool done)
453	   453	    {
454	   454	        return "<span class=\"ex-step " + (done ? "done" : "todo") + "\">"
455	   455	             + (done ? "&#10003; " : "&#9675; ") + HttpUtility.HtmlEncode(label) + "</span>";
456	   456	    }
457	   457	
458	   458	    // -- Save / recheck -------------------------------------------------------
459	   459	
460	   460	    private void HandleSave()
461	   461	    {
462	   462	        if (CurrentExitId <= 0)
463	   463	        {
464	   464	            ExPanel.JSProperties["cpMsg"] = "Open an exit first.";
465	   465	            return;
466	   466	        }
467	   467	
468	   468	        const string sql = @"
469	   469	            UPDATE dbo.HR_ExitFormality
470	   470	            SET    InterviewStatus         = @Status,
471	   471	                   InterviewDate           = @Date,
472	   472	                   InterviewByUserMasterID = @By,
473	   473	                   ReasonForLeaving        = @Reason,
474	   474	                   EmployeeFeedback        = @EmpFeedback,
475	   475	                   ManagerFeedback         = @MgrFeedback,
476	   476	                   EditUserMasterID        = @UserID,
477	   477	                   EditUserDateTime        = GETDATE()
478	   478	            WHERE  ExitFormalityID = @Id AND Status = 1";
479	   479	
480	   480	        using (SqlConnection conn = CreateConnection())
481	   481	        {
482	   482	            conn.Open();
483	   483	            using (var cmd = new SqlCommand(sql, conn))
484	   484	            {
485	   485	                cmd.Parameters.AddWithValue("@Status",
486	   486	                    Str(cmbInterviewStatus.Value, ExitFormalityService.InterviewPending));
487	   487	                cmd.Parameters.AddWithValue("@Date",
488	   488	                    dtInterview.Value == null ? (object)DBNull.Value : dtInterview.Date);
489	   489	                cmd.Parameters.AddWithValue("@By",
490	   490	                    cmbInterviewBy.Value == null ? (object)DBNull.Value : Convert.ToInt64(cmbInterviewBy.Value));
491	   491	                cmd.Parameters.AddWithValue("@Reason", Nullable(cmbReason.Value));
492	   492	                cmd.Parameters.AddWithValue("@EmpFeedback", Nullable(memEmployeeFeedback.Text));
493	   493	                cmd.Parameters.AddWithValue("@MgrFeedback", Nullable(memManagerFeedback.Text));
494	   494	                cmd.Parameters.AddWithValue("@UserID", UserId);
495	   495	                cmd.Parameters.AddWithValue("@Id", CurrentExitId);
496	   496	                cmd.ExecuteNonQuery();
497	   497	            }
498	   498	
499	   499	            // The interview is one of the three legs, so saving it changes the verdict.
500	   500	            using (SqlTransaction tx = conn.BeginTransaction())
501	   501	            {
502	   502	                try { ExitFormalityService.Evaluate(conn, tx, CurrentExitId); tx.Commit(); }
503	   503	                catch { try { tx.Rollback(); } catch { } throw; }
504	   504	            }
505	   505	        }
506	   506	
507	   507	        LoadExit(CurrentExitId);
508	   508	        ExPanel.JSProperties["cpMsg"] = "Saved.";
509	   509	    }
