511	   511	    /// <summary>
512	   512	    /// Re-reads asset returns and clearances and recomputes the verdict. Needed because both
513	   513	    /// move underneath the exit: a return is recorded in the Assets module, not here.
514	   514	    /// </summary>
515	   515	    private void HandleRecheck()
516	   516	    {
517	   517	        if (CurrentExitId <= 0) return;
518	   518	
519	   519	        using (SqlConnection conn = CreateConnection())
520	   520	        {
521	   521	            conn.Open();
522	   522	            using (SqlTransaction tx = conn.BeginTransaction())
523	   523	            {
524	   524	                try
525	   525	                {
526	   526	                    ExitFormalityService.SeedClearances(conn, tx, CurrentExitId);
527	   527	                    ExitFormalityService.Evaluate(conn, tx, CurrentExitId);
528	   528	                    tx.Commit();
529	   529	                }
530	   530	                catch { try { tx.Rollback(); } catch { } throw; }
531	   531	            }
532	   532	        }
533	   533	
534	   534	        LoadExit(CurrentExitId);
535	   535	        ExPanel.JSProperties["cpMsg"] = "Re-checked.";
536	   536	    }
