538	   538	    /// <summary>
539	   539	    /// Creates the F&amp;F case and carries every department due into it as a recovery, then
540	   540	    /// sends the user to the settlement screen. Both re-checked server-side: the callback is
541	   541	    /// reachable from a second tab whatever the toolbar is showing.
542	   542	    /// </summary>
543	   543	    private void HandleMakeCase()
544	   544	    {
545	   545	        if (CurrentExitId <= 0) return;
546	   546	
547	   547	        long employeeId = 0;
548	   548	        long caseId;
549	   549	        int duesPushed;
550	   550	
551	   551	        using (SqlConnection conn = CreateConnection())
552	   552	        {
553	   553	            conn.Open();
554	   554	
555	   555	            using (var cmd = new SqlCommand(@"
556	   556	                SELECT EmployeeMasterID, CAST(IsComplete AS int)
557	   557	                FROM   dbo.HR_ExitFormality WHERE ExitFormalityID = @Id AND Status = 1", conn))
558	   558	            {
559	   559	                cmd.Parameters.AddWithValue("@Id", CurrentExitId);
560	   560	                using (SqlDataReader rd = cmd.ExecuteReader())
561	   561	                {
562	   562	                    if (!rd.Read())
563	   563	                    {
564	   564	                        ExPanel.JSProperties["cpMsg"] = "That exit record no longer exists.";
565	   565	                        return;
566	   566	                    }
567	   567	                    employeeId = rd.GetInt64(0);
568	   568	                    if (rd.GetInt32(1) != 1)
569	   569	                    {
570	   570	                        ExPanel.JSProperties["cpMsg"] =
571	   571	                            "This exit is not complete yet, so no F&F case was created.";
572	   572	                        return;
573	   573	                    }
574	   574	                }
575	   575	            }
576	   576	
577	   577	            // Refuse a second live case for the same person rather than creating one and
578	   578	            // leaving two settlements to reconcile.
579	   579	            using (var cmd = new SqlCommand(@"
580	   580	                SELECT COUNT(*) FROM dbo.HR_FNFSettlement
581	   581	                WHERE  EmployeeMasterID = @Emp AND Status = 1 AND WorkflowStatus <> 'Cancelled'", conn))
582	   582	            {
583	   583	                cmd.Parameters.AddWithValue("@Emp", employeeId);
584	   584	                if (Convert.ToInt32(cmd.ExecuteScalar()) > 0)
585	   585	                {
586	   586	                    ExPanel.JSProperties["cpMsg"] =
587	   587	                        "This employee already has an F&F case. Open it from Full & Final Settlement.";
588	   588	                    return;
589	   589	                }
590	   590	            }
591	   591	
592	   592	            using (SqlTransaction tx = conn.BeginTransaction())
593	   593	            {
594	   594	                try
595	   595	                {
596	   596	                    caseId = FNFCaseService.CreateCase(conn, tx, employeeId, CompanyId, UserId,
597	   597	                                                       HostNameCapped(), 90);
598	   598	
599	   599	                    // Record which exit it came from, then carry the dues over.
600	   600	                    using (var cmd = new SqlCommand(
601	   601	                        "UPDATE dbo.HR_FNFSettlement SET ExitFormalityID = @ExitId WHERE FNFSettlementID = @CaseId",
602	   602	                        conn, tx))
603	   603	                    {
604	   604	                        cmd.Parameters.AddWithValue("@ExitId", CurrentExitId);
605	   605	                        cmd.Parameters.AddWithValue("@CaseId", caseId);
606	   606	                        cmd.ExecuteNonQuery();
607	   607	                    }
608	   608	
609	   609	                    duesPushed = ExitFormalityService.PushDuesToCase(conn, tx, CurrentExitId, caseId,
610	   610	                                                                     UserId, HostNameCapped());
611	   611	                    tx.Commit();
612	   612	                }
613	   613	                catch
614	   614	                {
615	   615	                    try { tx.Rollback(); } catch { /* connection already gone */ }
616	   616	                    throw;
617	   617	                }
618	   618	            }
619	   619	        }
620	   620	
621	   621	        ExPanel.JSProperties["cpMsg"] = "F&F case created"
622	   622	            + (duesPushed > 0 ? " with " + duesPushed + " recovery line(s) from department dues." : ".")
623	   623	            + " Opening Full & Final Settlement.";
624	   624	        ExPanel.JSProperties["cpGoToCase"] = ResolveUrl("~/Payroll/FNFSettlement.aspx");
625	   625	    }
