657	   657	    private DataTable LoadClearances()
658	   658	    {
659	   659	        var table = new DataTable();
660	   660	        if (CurrentExitId <= 0) return table;
661	   661	
662	   662	        const string sql = @"
663	   663	            SELECT C.ExitClearanceID, C.DepartmentCode, C.DepartmentName, C.ChecklistHint,
664	   664	                   C.ClearanceStatus, C.Remarks, ISNULL(C.DuesAmount, 0) AS DuesAmount,
665	   665	                   C.DuesDescription, C.ClearedOn, C.SortOrder,
666	   666	                   ISNULL(U.UserName, '') AS ClearedByName
667	   667	            FROM   dbo.HR_ExitClearance C
668	   668	            LEFT   JOIN dbo.HR_UserMaster U ON U.UserMasterID = C.ClearedByUserMasterID
669	   669	            WHERE  C.ExitFormalityID = @Id
670	   670	            ORDER  BY C.SortOrder, C.ExitClearanceID";
671	   671	
672	   672	        try
673	   673	        {
674	   674	            using (SqlConnection conn = CreateConnection())
675	   675	            using (var cmd = new SqlCommand(sql, conn))
676	   676	            {
677	   677	                cmd.Parameters.AddWithValue("@Id", CurrentExitId);
678	   678	                using (var da = new SqlDataAdapter(cmd)) da.Fill(table);
679	   679	            }
680	   680	        }
681	   681	        catch (Exception ex)
