688	   688	    protected void ClearanceGrid_RowUpdating(object sender, DevExpress.Web.Data.ASPxDataUpdatingEventArgs e)
689	   689	    {
690	   690	        e.Cancel = true;
691	   691	        try
692	   692	        {
693	   693	            if (CurrentExitId <= 0)
694	   694	            {
695	   695	                ExPanel.JSProperties["cpMsg"] = "Open an exit first.";
696	   696	                ClearanceGrid.CancelEdit();
697	   697	                return;
698	   698	            }
699	   699	
700	   700	            string status = Str(e.NewValues["ClearanceStatus"], ExitFormalityService.ClearancePending);
701	   701	            decimal dues = Money(e.NewValues["DuesAmount"]);
702	   702	
703	   703	            // An objection with an amount is how a due gets recorded; without a description
704	   704	            // the F&F recovery line would read as an unexplained deduction.
705	   705	            if (status == ExitFormalityService.ClearanceObjection && dues > 0
706	   706	                && string.IsNullOrEmpty(Convert.ToString(e.NewValues["DuesDescription"])))
707	   707	            {
708	   708	                ExPanel.JSProperties["cpMsg"] =
709	   709	                    "Say what the dues are for - it becomes the description on the F&F recovery line.";
710	   710	                return;     // leave the row in edit so the text can be typed
711	   711	            }
712	   712	
713	   713	            // Only stamp who cleared it when an actual answer was given, so re-saving a
714	   714	            // still-Pending row does not claim somebody answered it.
715	   715	            bool answered = (status != ExitFormalityService.ClearancePending);
716	   716	
717	   717	            const string sql = @"
718	   718	                UPDATE dbo.HR_ExitClearance
719	   719	                SET    ClearanceStatus = @Status,
720	   720	                       Remarks         = @Remarks,
721	   721	                       DuesAmount      = @Dues,
722	   722	                       DuesDescription = @DuesDesc,
723	   723	                       ClearedByUserMasterID = CASE WHEN @Answered = 1 THEN @UserID ELSE NULL END,
724	   724	                       ClearedOn             = CASE WHEN @Answered = 1 THEN GETDATE() ELSE NULL END
725	   725	                WHERE  ExitClearanceID = @RowId AND ExitFormalityID = @ExitId";
726	   726	
727	   727	            using (SqlConnection conn = CreateConnection())
728	   728	            {
729	   729	                conn.Open();
730	   730	                using (var cmd = new SqlCommand(sql, conn))
731	   731	                {
732	   732	                    cmd.Parameters.AddWithValue("@Status", status);
733	   733	                    cmd.Parameters.AddWithValue("@Remarks", Nullable(e.NewValues["Remarks"]));
734	   734	                    cmd.Parameters.AddWithValue("@Dues", dues);
735	   735	                    cmd.Parameters.AddWithValue("@DuesDesc", Nullable(e.NewValues["DuesDescription"]));
736	   736	                    cmd.Parameters.AddWithValue("@Answered", answered);
737	   737	                    cmd.Parameters.AddWithValue("@UserID", UserId);
738	   738	                    cmd.Parameters.AddWithValue("@RowId", Convert.ToInt64(e.Keys[ClearanceGrid.KeyFieldName]));
739	   739	                    cmd.Parameters.AddWithValue("@ExitId", CurrentExitId);
740	   740	                    cmd.ExecuteNonQuery();
741	   741	                }
742	   742	
743	   743	                using (SqlTransaction tx = conn.BeginTransaction())
744	   744	                {
745	   745	                    try { ExitFormalityService.Evaluate(conn, tx, CurrentExitId); tx.Commit(); }
746	   746	                    catch { try { tx.Rollback(); } catch { } throw; }
747	   747	                }
748	   748	            }
749	   749	
750	   750	            ClearanceGrid.CancelEdit();
751	   751	            LoadExit(CurrentExitId);      // refreshes the banner, the steps and the dues total
752	   752	        }
753	   753	        catch (Exception ex)
754	   754	        {
755	   755	            ErrorLogHelper.Log(ex, "ExitFormality.ClearanceUpdate");
756	   756	            ExPanel.JSProperties["cpMsg"] = ErrorLogHelper.FriendlyMessage;
757	   757	        }
758	   758	    }
