760	   760	    // -- helpers --------------------------------------------------------------
761	   761	
762	   762	    private static string Str(object value, string fallback)
763	   763	    {
764	   764	        string text = Convert.ToString(value);
765	   765	        return string.IsNullOrEmpty(text) ? fallback : text;
766	   766	    }
767	   767	
768	   768	    private static object Nullable(object value)
769	   769	    {
770	   770	        string text = Convert.ToString(value);
771	   771	        return string.IsNullOrEmpty(text) ? (object)DBNull.Value : text;
772	   772	    }
773	   773	
774	   774	    private static decimal Money(object value)
775	   775	    {
776	   776	        if (value == null || value == DBNull.Value) return 0m;
777	   777	        decimal amount;
778	   778	        return decimal.TryParse(Convert.ToString(value), out amount) ? amount : 0m;
779	   779	    }
780	   780	}
