130	    protected void ExitGridView_BeforePerformDataSelect(object sender, EventArgs e)
131	    {
132	        // Supplied here rather than only on the first request: paging, sorting, the page-size
133	        // picker and the filter row all raise the GRID's own callback, which passes through
134	        // neither Page_Load's !IsPostBack branch nor the panel handler.
