231	    private void HandleNew()
232	    {
233	        CurrentExitId = 0;
234	
235	        txtExitNo.Text = string.Empty;
236	        cmbEmployee.Value = null;
237	        cmbEmployee.Enabled = true;
238	        cmbInterviewStatus.Value = ExitFormalityService.InterviewPending;
239	        dtInterview.Value = null;
240	        cmbInterviewBy.Value = null;
241	        cmbReason.Value = null;
242	        memEmployeeFeedback.Text = string.Empty;
243	        memManagerFeedback.Text = string.Empty;
244	        litBanner.Text = string.Empty;
245	
246	        int waiting = LoadEmployeesNeedingExit();
247	
248	        if (waiting == 0)
249	        {
250	            litSnapshot.Text =
251	                "<div class=\"ex-banner blocked\">Nobody in this company needs an exit record.</div>"
252	              + "<div class=\"ex-kv\">The list only offers employees who have a <b>Date Of Resign</b> "
253	              + "or a <b>Date Of Left</b> on their record and do not already have one. Set the "
254	              + "resignation date in <b>Employee &#8594; Employee</b> first.</div>";
255	        }
256	        else
257	        {
258	            string count = waiting < 0
259	                ? "The employee list could not be read - check HR_ErrorLog."
260	                : waiting + " employee" + (waiting == 1 ? "" : "s") + " awaiting exit formality.";
261	
262	            litSnapshot.Text = "<div class=\"ex-kv\">" + HttpUtility.HtmlEncode(count)
263	                + " Pick one and press <b>Open Exit</b>. Their dates, department and manager are "
264	                + "copied from the employee record, and the five department clearance rows are "
265	                + "created automatically.</div>";
266	        }
267	
268	        ExPanel.JSProperties["cpCreating"] = "1";
269	        ExPanel.JSProperties["cpComplete"] = "0";
270	        ExPanel.JSProperties["cpNoEligible"] = (waiting == 0) ? "1" : "0";
271	    }
