383	    private static string Cell(string label, object value)
384	    {
385	        string text = (value == null || value == DBNull.Value || Convert.ToString(value).Length == 0)
386	            ? "<i style=\"color:#999\">not set</i>"
387	            : HttpUtility.HtmlEncode(Convert.ToString(value));
388	
389	        return "<td style=\"padding:4px 14px 4px 0;white-space:nowrap\"><span style=\"color:#777\">" +
390	               HttpUtility.HtmlEncode(label) + "</span><br /><b>" + text + "</b></td>";
391	    }
