452	    private static string Step(string label, bool done)
453	    {
454	        return "<span class=\"ex-step " + (done ? "done" : "todo") + "\">"
455	             + (done ? "&#10003; " : "&#9675; ") + HttpUtility.HtmlEncode(label) + "</span>";
456	    }
