    /// Accepts anyone with a real ResignDate OR DateOfLeft - not JobStatus = 'Left' -
    /// because a case is normally raised during the notice period, while the employee
    /// is still Active. Both dates carry the 1900-01-01 sentinel, so both need the
    /// epoch test.
    /// </summary>
    /// <summary>
    /// Adds the Exit Formality gate to the eligibility query when this company requires it
    /// (HR_FNFConfig.RequireExitFormality, on by default): no settlement until the exit
    /// interview is done, every asset is back and every department has cleared.
    ///
    /// Returns an empty string when the exit tables are absent or the company has the gate
    /// switched off, so the caller can splice it in unconditionally. It has to be appended
    /// rather than written inline because SQL naming a missing table fails at PARSE time,
    /// and a tenant database may not have migration 114 yet.
    /// </summary>
    private static string ExitFormalityGate(SqlConnection conn, SqlTransaction tx, long companyId)
    {
        if (!ExitFormalityService.SchemaReady(conn, tx)) return string.Empty;

        bool required;
        using (var cmd = new SqlCommand(@"
            SELECT ISNULL(MAX(CAST(RequireExitFormality AS int)), 1)
            FROM   dbo.HR_FNFConfig
            WHERE  CompanyMasterID = @CompanyID AND Status = 1", conn, tx))
        {
            cmd.Parameters.AddWithValue("@CompanyID", companyId);
            object value = cmd.ExecuteScalar();
            required = (value == null || value == DBNull.Value) || Convert.ToInt32(value) == 1;
        }

        if (!required) return string.Empty;

        return @"
              AND EXISTS (SELECT 1 FROM dbo.HR_ExitFormality X
                          WHERE  X.EmployeeMasterID = EM.EmployeeMasterID
                            AND  X.Status = 1
                            AND  X.IsComplete = 1) ";
    }

    /// <param name="tx">Pass null outside a transaction. Required when the connection
    /// already has one open, otherwise ADO.NET refuses the read with "ExecuteReader
    /// requires the command to have a transaction".</param>
    public static DataTable EligibleEmployees(SqlConnection conn, SqlTransaction tx, long companyId)
    {
        const string sql = @"
            SELECT EM.EmployeeMasterID,
                   LTRIM(ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.FirstName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.FatherName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.LastName)),''), ''))
                       + ' (' + ISNULL(EM.Code, '') + ')' AS Name
            FROM   dbo.HR_EmployeeMaster EM
            WHERE  EM.Status = 1
              AND  EM.CompanyMasterID = @CompanyID
              AND  ( (EM.ResignDate IS NOT NULL AND EM.ResignDate > @Epoch)
                  OR (EM.DateOfLeft IS NOT NULL AND EM.DateOfLeft > @Epoch) )
              AND  NOT EXISTS (SELECT 1 FROM dbo.HR_FNFSettlement F
                               WHERE  F.EmployeeMasterID = EM.EmployeeMasterID
                                 AND  F.Status = 1
                                 AND  F.WorkflowStatus <> @Cancelled)";

        // Exit Formality must be complete first, when the company requires it. Appended
        // because it references tables a tenant database may not have yet.
        string gated = sql + ExitFormalityGate(conn, tx, companyId) + " ORDER BY EM.Code";

        using (var cmd = new SqlCommand(gated, conn, tx))
        {
            cmd.Parameters.AddWithValue("@CompanyID", companyId);
            cmd.Parameters.AddWithValue("@Epoch", EpochDate);
            cmd.Parameters.AddWithValue("@Cancelled", StatusCancelled);

            var dt = new DataTable();
            using (var da = new SqlDataAdapter(cmd)) da.Fill(dt);
            return dt;
        }
    }

    // -------------------------------------------------------------------------
    //  Create case
    // -------------------------------------------------------------------------

    /// <summary>
    /// Creates the case, copies the employee snapshot, seeds the readiness checklist,
    /// auto-answers the checks this app can answer, discovers the recoveries it can
    /// see, and evaluates the clearance verdict.
    ///
    /// The CALLER owns the transaction - all six steps must commit together or a case
    /// exists with a half-built checklist, and a caller-owned transaction is also what
    /// makes this testable against the live database without writing to it.
