        if (cmbEmployee.Value == null)
        {
            FnfPanel.JSProperties["cpMsg"] = "Pick the employee to settle first.";
            return;
        }

        long employeeId = Convert.ToInt64(cmbEmployee.Value);
        int windowDays = ComplianceWindowDaysForCompany();
        long newId;

        using (SqlConnection conn = CreateConnection())
        {
            conn.Open();
            // One transaction for the whole thing: the header, the nine checklist rows, the
            // auto-answers, the discovered recoveries and the clearance verdict. A case must
            // never exist with a half-built checklist.
            using (SqlTransaction tx = conn.BeginTransaction())
            {
