    82	    /// <summary>
    83	    /// Everyone who has actually left — the only people an alumni record makes sense for.
    84	    /// Epoch-aware: the lifecycle dates carry 1900-01-01 when unset, so a plain NULL test would
    85	    /// match the whole company.
    86	    /// </summary>
    87	    private void BindEmployeeColumn()
    88	    {
    89	        const string sql = @"
    90	            SELECT EM.EmployeeMasterID,
    91	                   LTRIM(ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.FirstName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.FatherName)),''), '') + ISNULL(' ' + NULLIF(LTRIM(RTRIM(EM.LastName)),''), ''))
    92	                       + ' (' + ISNULL(EM.Code, '') + ')' AS Name
    93	            FROM   dbo.HR_EmployeeMaster EM
    94	            WHERE  EM.CompanyMasterID = @CompanyID
    95	              AND  ( (EM.ResignDate IS NOT NULL AND EM.ResignDate > @Epoch)
    96	                  OR (EM.DateOfLeft IS NOT NULL AND EM.DateOfLeft > @Epoch)
    97	                  OR  EM.JobStatus = 'Left' )
    98	            ORDER BY EM.Code";
    99	
   100	        try
   101	        {
   102	            using (SqlConnection conn = CreateConnection())
   103	            using (var cmd = new SqlCommand(sql, conn))
   104	            {
   105	                cmd.Parameters.AddWithValue("@CompanyID", CompanyId);
   106	                cmd.Parameters.AddWithValue("@Epoch", ExitFormalityService.EpochDate);
   107	                var dt = new DataTable();
   108	                using (var da = new SqlDataAdapter(cmd)) da.Fill(dt);
   109	
   110	                var col = AlumniGrid.Columns["EmployeeMasterID"] as GridViewDataComboBoxColumn;
   111	                if (col != null)
   112	                {
   113	                    // No DataBind() here: ComboBoxProperties has no such method (reflected -
   114	                    // it is not an editor, just the column's settings). Assigning the source
   115	                    // is enough; the grid's own bind renders it.
   116	                    col.PropertiesComboBox.DataSource = dt;
   117	                    col.PropertiesComboBox.ValueField = "EmployeeMasterID";
   118	                    col.PropertiesComboBox.ValueType = typeof(long);
   119	                    col.PropertiesComboBox.TextField = "Name";
   120	                }
   121	            }
   122	        }
   123	        catch (Exception ex)
   124	        {
   125	            ErrorLogHelper.Log(ex, "AlumniRegister.BindEmployees");
   126	        }
   127	    }
