   138	    private DataTable LoadAlumni()
   139	    {
   140	        const string sql = @"
   141	            SELECT A.FNFAlumniID, A.EmployeeMasterID, A.FNFSettlementID,
   142	                   A.ReasonForLeaving, A.ManagerFeedback, A.EligibleForRehire,
   143	                   ISNULL(A.BlacklistFlag, 0) AS BlacklistFlag, A.BlacklistReason, A.HRRemarks,
   144	                   ISNULL(EM.Code, '') AS EmployeeCode,
   145	                   NULLIF(EM.DateOfLeft, '1900-01-01') AS DateOfLeft,
   146	                   ISNULL(F.CaseNo, '') AS CaseNo
   147	            FROM   dbo.HR_FNFAlumni A
   148	            LEFT   JOIN dbo.HR_EmployeeMaster EM ON EM.EmployeeMasterID = A.EmployeeMasterID
   149	            LEFT   JOIN dbo.HR_FNFSettlement  F  ON F.FNFSettlementID   = A.FNFSettlementID
   150	            WHERE  A.Status = 1 AND A.CompanyMasterID = @CompanyID
   151	            ORDER  BY A.FNFAlumniID DESC";
   152	
   153	        var table = new DataTable();
   154	        try
   155	        {
   156	            using (SqlConnection conn = CreateConnection())
   157	            using (var cmd = new SqlCommand(sql, conn))
   158	            {
   159	                cmd.Parameters.AddWithValue("@CompanyID", CompanyId);
   160	                using (var da = new SqlDataAdapter(cmd)) da.Fill(table);
   161	            }
   162	        }
   163	        catch (Exception ex)
   164	        {
   165	            ErrorLogHelper.Log(ex, "AlumniRegister.Load");
   166	        }
   167	        return table;
