   171	    /// Two rules, both enforced with <c>e.RowError</c> rather than an alert: RowError keeps the
   172	    /// popup open with the message attached, whereas an alert closes the form and throws away
   173	    /// everything typed.
   174	    /// </summary>
   175	    protected void AlumniGrid_RowValidating(object sender, ASPxDataValidationEventArgs e)
   176	    {
   177	        if (!IsAllowed) { e.RowError = "You do not have access to this register."; return; }
   178	
   179	        object employee = e.NewValues["EmployeeMasterID"];
   180	        if (employee == null || employee == DBNull.Value)
   181	        {
   182	            e.RowError = "Pick the employee this record is about.";
   183	            return;
   184	        }
   185	
   186	        // Blacklisting somebody without saying why is the one thing here that could damage a
   187	        // person's prospects with no explanation on file.
   188	        bool blacklisted = e.NewValues["BlacklistFlag"] != null &&
   189	                           Convert.ToBoolean(e.NewValues["BlacklistFlag"]);
   190	        string reason = Convert.ToString(e.NewValues["BlacklistReason"]);
   191	
   192	        if (blacklisted && string.IsNullOrEmpty((reason ?? string.Empty).Trim()))
   193	        {
   194	            e.RowError = "Give the reason for blacklisting - it must not sit on the record unexplained.";
   195	            return;
   196	        }
   197	
   198	        // One live record per employee, or two people reach different conclusions about the
   199	        // same person.
   200	        long employeeId = Convert.ToInt64(employee);
   201	        long excludeId = e.IsNewRow ? 0 : Convert.ToInt64(e.Keys[AlumniGrid.KeyFieldName]);
   202	
   203	        try
   204	        {
   205	            using (SqlConnection conn = CreateConnection())
   206	            using (var cmd = new SqlCommand(@"
   207	                SELECT COUNT(*) FROM dbo.HR_FNFAlumni
   208	                WHERE  EmployeeMasterID = @Emp AND Status = 1 AND FNFAlumniID <> @Exclude", conn))
   209	            {
   210	                cmd.Parameters.AddWithValue("@Emp", employeeId);
   211	                cmd.Parameters.AddWithValue("@Exclude", excludeId);
   212	                conn.Open();
   213	                if (Convert.ToInt32(cmd.ExecuteScalar()) > 0)
   214	                    e.RowError = "This employee already has an alumni record. Edit that one instead.";
   215	            }
   216	        }
   217	        catch (Exception ex)
   218	        {
   219	            ErrorLogHelper.Log(ex, "AlumniRegister.Validate");
   220	            e.RowError = ErrorLogHelper.FriendlyMessage;
   221	        }
   222	    }
