   162	    private const string _SelectSql = @"
   163	        SELECT a.FNFAlumniID AS FnfAlumniId, a.EmployeeMasterID AS EmployeeMasterId,
   164	               a.FNFSettlementID AS FnfSettlementId, a.ReasonForLeaving, a.ManagerFeedback,
   165	               a.EligibleForRehire, a.BlacklistFlag, a.BlacklistReason, a.HRRemarks AS HrRemarks,
   166	               ISNULL(LTRIM(ISNULL(' ' + NULLIF(LTRIM(RTRIM(em.FirstName)),''), '')
   167	                          + ISNULL(' ' + NULLIF(LTRIM(RTRIM(em.FatherName)),''), '')
   168	                          + ISNULL(' ' + NULLIF(LTRIM(RTRIM(em.LastName)),''), '')), '') AS EmployeeName,
   169	               ISNULL(em.Code, '') AS EmployeeCode,
   170	               f.CaseNo
   171	        FROM   HR_FNFAlumni a
   172	        LEFT   JOIN HR_EmployeeMaster em ON em.EmployeeMasterID = a.EmployeeMasterID
   173	        LEFT   JOIN HR_FNFSettlement f ON f.FNFSettlementID = a.FNFSettlementID";
   174	
   175	    public async Task<List<ListFnfAlumniModel>> GetAllAsync(long companyMasterId)
   176	    {
   177	        var sql = $"{_SelectSql} WHERE a.Status = 1 AND a.CompanyMasterID = @CompanyMasterId ORDER BY a.FNFAlumniID DESC";
   178	        var res = await _repo.QueryAsync<ListFnfAlumniModel>(sql, new { CompanyMasterId = companyMasterId });
   179	        return res.ToList();
   180	    }
