   182	    public async Task<ListFnfAlumniModel?> GetByIdAsync(long id, long companyMasterId)
   183	    {
   184	        var sql = $"{_SelectSql} WHERE a.Status = 1 AND a.FNFAlumniID = @Id AND a.CompanyMasterID = @CompanyMasterId";
   185	        return await _repo.QueryFirstOrDefaultAsync<ListFnfAlumniModel>(sql, new { Id = id, CompanyMasterId = companyMasterId });
   186	    }
