   188	    public async Task<bool> HasLiveRecordAsync(long employeeMasterId, long excludeAlumniId)
   189	    {
   190	        const string sql = @"
   191	            SELECT COUNT(1) FROM HR_FNFAlumni
   192	            WHERE EmployeeMasterID = @EmployeeMasterId AND Status = 1 AND FNFAlumniID <> @ExcludeAlumniId";
   193	        var count = await _repo.ExecuteScalarAsync<int>(sql,
   194	            new { EmployeeMasterId = employeeMasterId, ExcludeAlumniId = excludeAlumniId });
   195	        return count > 0;
   196	    }
