   198	    public async Task<long> AddAsync(AddFnfAlumniModel model, long userId, long companyId)
   199	    {
   200	        await _tx.BeginTransactionAsync();
   201	        try
   202	        {
   203	            // FNFSettlementID is always NULL here - a manually-created record has no case behind
   204	            // it. AddFromSettlementAsync below is the only path that sets it.
   205	            const string sql = @"
   206	                INSERT INTO HR_FNFAlumni
   207	                    (EmployeeMasterID, FNFSettlementID, ReasonForLeaving, ManagerFeedback,
   208	                     EligibleForRehire, BlacklistFlag, BlacklistReason, HRRemarks, CompanyMasterID,
   209	                     Status, EntryUserMasterID, EntryUserDateTime, SystemName)
   210	                OUTPUT INSERTED.FNFAlumniID
   211	                VALUES
   212	                    (@EmployeeMasterId, NULL, @ReasonForLeaving, @ManagerFeedback,
   213	                     @EligibleForRehire, @BlacklistFlag, @BlacklistReason, @HrRemarks, @CompanyId,
   214	                     1, @UserId, @Now, @SystemName)";
   215	
   216	            var newId = await _repo.QueryFirstOrDefaultAsync<long>(sql, new
   217	            {
   218	                model.EmployeeMasterId, model.ReasonForLeaving, model.ManagerFeedback,
   219	                model.EligibleForRehire, model.BlacklistFlag,
   220	                BlacklistReason = model.BlacklistFlag ? model.BlacklistReason?.Trim() : null,
   221	                model.HrRemarks, CompanyId = companyId, UserId = userId, Now = DateTime.Now,
   222	                SystemName = "HRMS_WEB",
   223	            });
   224	
   225	            await _tx.CommitAsync();
   226	            return newId;
   227	        }
   228	        catch { await _tx.RollbackAsync(); throw; }
   229	    }
