   232	    {
   233	        await _tx.BeginTransactionAsync();
   234	        try
   235	        {
   236	            // FNFSettlementID, CompanyMasterID, Status, and the Entry* audit pair are untouched.
   237	            const string sql = @"
   238	                UPDATE HR_FNFAlumni
   239	                SET    EmployeeMasterID = @EmployeeMasterId, ReasonForLeaving = @ReasonForLeaving,
   240	                       ManagerFeedback = @ManagerFeedback, EligibleForRehire = @EligibleForRehire,
   241	                       BlacklistFlag = @BlacklistFlag, BlacklistReason = @BlacklistReason,
   242	                       HRRemarks = @HrRemarks, EditUserMasterID = @UserId, EditUserDateTime = @Now
   243	                WHERE  FNFAlumniID = @Id AND CompanyMasterID = @CompanyMasterId";
   244	
   245	            await _repo.ExecuteAsync(sql, new
   246	            {
   247	                model.EmployeeMasterId, model.ReasonForLeaving, model.ManagerFeedback,
   248	                model.EligibleForRehire, model.BlacklistFlag,
   249	                BlacklistReason = model.BlacklistFlag ? model.BlacklistReason?.Trim() : null,
   250	                model.HrRemarks, UserId = userId, Now = DateTime.Now,
   251	                Id = model.FnfAlumniId, CompanyMasterId = companyMasterId,
   252	            });
   253	
   254	            await _tx.CommitAsync();
   255	        }
   256	        catch { await _tx.RollbackAsync(); throw; }
   257	    }
