   260	    {
   261	        await _tx.BeginTransactionAsync();
   262	        try
   263	        {
   264	            const string sql = @"
   265	                UPDATE HR_FNFAlumni SET Status = 0, EditUserMasterID = @UserId, EditUserDateTime = @Now
   266	                WHERE  FNFAlumniID = @Id AND CompanyMasterID = @CompanyMasterId";
   267	            await _repo.ExecuteAsync(sql, new { UserId = userId, Now = DateTime.Now, Id = id, CompanyMasterId = companyMasterId });
   268	            await _tx.CommitAsync();
   269	        }
   270	        catch { await _tx.RollbackAsync(); throw; }
