   283	                    (EmployeeMasterID, FNFSettlementID, ReasonForLeaving, ManagerFeedback,
   284	                     EligibleForRehire, BlacklistFlag, CompanyMasterID, Status,
   285	                     EntryUserMasterID, EntryUserDateTime, SystemName)
   286	                VALUES
   287	                    (@EmployeeMasterId, @FnfSettlementId, @ReasonForLeaving, @ManagerFeedback,
   288	                     NULL, 0, @CompanyId, 1, @UserId, @Now, @SystemName)";
   289	
   290	            await _repo.ExecuteAsync(sql, new
   291	            {
   292	                EmployeeMasterId = employeeMasterId, FnfSettlementId = fnfSettlementId,
   293	                ReasonForLeaving = reasonForLeaving, ManagerFeedback = managerFeedback,
   294	                CompanyId = companyId, UserId = userId, Now = DateTime.Now, SystemName = "HRMS_WEB",
   295	            });
