        #region F&amp;F Configuration reuse (01_FNFConfiguration.md)
        public async Task<List<HrLeaveMaster>> GetEncashableCandidates(long companyMasterId)
        {
            return await _hrmsystemContext.HrLeaveMasters
                .AsNoTracking()
                .Where(x => x.IsActive && (x.CompanyMasterId == companyMasterId || x.CompanyMasterId == null))
                .OrderBy(x => x.Name)
                .ToListAsync();
        }

        public async Task UpdateEncashableFlag(int leaveMasterId, bool isEncashable)
        {
            var entity = await _hrmsystemContext.HrLeaveMasters.FirstOrDefaultAsync(x => x.LeaveMasterId == leaveMasterId);
            if (entity == null) return;
            entity.IsEncashable = isEncashable;
            await _hrmsystemContext.SaveChangesAsync();
        }

        public async Task<int> CountEncashable(long companyMasterId)
        {
            return await _hrmsystemContext.HrLeaveMasters
                .AsNoTracking()
                .Where(x => x.IsActive && x.IsEncashable
                         && (x.CompanyMasterId == companyMasterId || x.CompanyMasterId == null))
                .CountAsync();
        }
        #endregion
    }
}
